INSERT INTO `snmp_credential` VALUES (1, 'v2-public', '', 2, '{\"readCommunity\":\"public\"}', 161);
INSERT INTO `snmp_mib` VALUES (1, 'AGENTX-MIB', 'AGENTX-MIB.txt', , '', '', 1, '2021-09-29 11:55:20', '{\"AGENTX-MIB\":[{\"index\":[],\"name\":\"agentxMIB\",\"objectID\":\"1.3.6.1.2.1.74\",\"pid\":\"1.3.6.1.2.1\",\"subTree\":[{\"index\":[],\"name\":\"agentxObjects\",\"objectID\":\"1.3.6.1.2.1.74.1\",\"pid\":\"1.3.6.1.2.1.74\",\"subTree\":[{\"index\":[],\"name\":\"agentxGeneral\",\"objectID\":\"1.3.6.1.2.1.74.1.1\",\"pid\":\"1.3.6.1.2.1.74.1\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The default length of time, in seconds, that the master\\nagent should allow to elapse after dispatching a message\\nto a session before it regards the subagent as not\\nresponding.  This is a system-wide value that may\\noverride the timeout value associated with a particular\\nsession (agentxSessionTimeout) or a particular registered\\nMIB region (agentxRegTimeout).  If the associated value of\\nagentxSessionTimeout and agentxRegTimeout are zero, or\\nimpractical in accordance with implementation-specific\\nprocedure of the master agent, the value represented by\\nthis object will be the effective timeout value for the\\n\\nmaster agent to await a response to a dispatch from a\\ngiven subagent.\\n\",\"index\":[],\"name\":\"agentxDefaultTimeout\",\"objectID\":\"1.3.6.1.2.1.74.1.1.1\",\"pid\":\"1.3.6.1.2.1.74.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The AgentX protocol version supported by this master agent.\\nThe current protocol version is 1.  Note that the master agent\\nmust also allow interaction with earlier version subagents.\\n\",\"index\":[],\"name\":\"agentxMasterAgentXVer\",\"objectID\":\"1.3.6.1.2.1.74.1.1.2\",\"pid\":\"1.3.6.1.2.1.74.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"agentxConnection\",\"objectID\":\"1.3.6.1.2.1.74.1.2\",\"pid\":\"1.3.6.1.2.1.74.1\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The value of sysUpTime when the last row creation or deletion\\noccurred in the agentxConnectionTable.\\n\",\"index\":[],\"name\":\"agentxConnTableLastChange\",\"objectID\":\"1.3.6.1.2.1.74.1.2.1\",\"pid\":\"1.3.6.1.2.1.74.1.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"The agentxConnectionTable tracks all current AgentX transport\\nconnections.  There may be zero, one, or more AgentX sessions\\ncarried on a given AgentX connection.\\n\",\"index\":[],\"name\":\"agentxConnectionTable\",\"objectID\":\"1.3.6.1.2.1.74.1.2.2\",\"pid\":\"1.3.6.1.2.1.74.1.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"An agentxConnectionEntry contains information describing a\\nsingle AgentX transport connection.  A connection may be\\n\\nused to support zero or more AgentX sessions.  An entry is\\ncreated when a new transport connection is established,\\nand is destroyed when the transport connection is terminated.\\n\",\"index\":[\"1.3.6.1.2.1.74.1.2.2.1.1\"],\"name\":\"agentxConnectionEntry\",\"objectID\":\"1.3.6.1.2.1.74.1.2.2.1\",\"pid\":\"1.3.6.1.2.1.74.1.2.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"agentxConnIndex contains the value that uniquely identifies\\nan open transport connection used by this master agent\\nto provide AgentX service.  Values of this index should\\nnot be re-used.  The value assigned to a given transport\\nconnection is constant for the lifetime of that connection.\\n\",\"index\":[],\"name\":\"agentxConnIndex\",\"objectID\":\"1.3.6.1.2.1.74.1.2.2.1.1\",\"pid\":\"1.3.6.1.2.1.74.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The value of sysUpTime when this connection was established\\nand, therefore, its value when this entry was added to the table.\\n\",\"index\":[],\"name\":\"agentxConnOpenTime\",\"objectID\":\"1.3.6.1.2.1.74.1.2.2.1.2\",\"pid\":\"1.3.6.1.2.1.74.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The transport protocol in use for this connection to the\\nsubagent.\\n\",\"index\":[],\"name\":\"agentxConnTransportDomain\",\"objectID\":\"1.3.6.1.2.1.74.1.2.2.1.3\",\"pid\":\"1.3.6.1.2.1.74.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OBJECT IDENTIFIER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The transport address of the remote (subagent) end of this\\nconnection to the master agent.  This object may be zero-length\\nfor unix-domain sockets (and possibly other types of transport\\naddresses) since the subagent need not bind a filename to its\\nlocal socket.\\n\",\"index\":[],\"name\":\"agentxConnTransportAddress\",\"objectID\":\"1.3.6.1.2.1.74.1.2.2.1.4\",\"pid\":\"1.3.6.1.2.1.74.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"}],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"agentxSession\",\"objectID\":\"1.3.6.1.2.1.74.1.3\",\"pid\":\"1.3.6.1.2.1.74.1\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The value of sysUpTime when the last row creation or deletion\\noccurred in the agentxSessionTable.\\n\",\"index\":[],\"name\":\"agentxSessionTableLastChange\",\"objectID\":\"1.3.6.1.2.1.74.1.3.1\",\"pid\":\"1.3.6.1.2.1.74.1.3\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"A table of AgentX subagent sessions currently in effect.\\n\",\"index\":[],\"name\":\"agentxSessionTable\",\"objectID\":\"1.3.6.1.2.1.74.1.3.2\",\"pid\":\"1.3.6.1.2.1.74.1.3\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"Information about a single open session between the AgentX\\nmaster agent and a subagent is contained in this entry.  An\\nentry is created when a new session is successfully established\\nand is destroyed either when the subagent transport connection\\nhas terminated or when the subagent session is closed.\\n\",\"index\":[\"1.3.6.1.2.1.74.1.2.2.1.1\",\"1.3.6.1.2.1.74.1.3.2.1.1\"],\"name\":\"agentxSessionEntry\",\"objectID\":\"1.3.6.1.2.1.74.1.3.2.1\",\"pid\":\"1.3.6.1.2.1.74.1.3.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"A unique index for the subagent session.  It is the same as\\nh.sessionID defined in the agentx header.  Note that if\\na subagent\'s session with the master agent is closed for\\nany reason its index should not be re-used.\\nA value of zero(0) is specifically allowed in order\\nto be compatible with the definition of h.sessionId.\\n\",\"index\":[],\"name\":\"agentxSessionIndex\",\"objectID\":\"1.3.6.1.2.1.74.1.3.2.1.1\",\"pid\":\"1.3.6.1.2.1.74.1.3.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"This is taken from the o.id field of the agentx-Open-PDU.\\nThis attribute will report a value of \'0.0\' for subagents\\nnot supporting the notion of an AgentX session object\\nidentifier.\\n\",\"index\":[],\"name\":\"agentxSessionObjectID\",\"objectID\":\"1.3.6.1.2.1.74.1.3.2.1.2\",\"pid\":\"1.3.6.1.2.1.74.1.3.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OBJECT IDENTIFIER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"A textual description of the session.  This is analogous to\\nsysDescr defined in the SNMPv2-MIB in RFC 1907 [19] and is\\ntaken from the o.descr field of the agentx-Open-PDU.\\nThis attribute will report a zero-length string value for\\nsubagents not supporting the notion of a session description.\\n\",\"index\":[],\"name\":\"agentxSessionDescr\",\"objectID\":\"1.3.6.1.2.1.74.1.3.2.1.3\",\"pid\":\"1.3.6.1.2.1.74.1.3.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The administrative (desired) status of the session.  Setting\\nthe value to \'down(2)\' closes the subagent session (with c.reason\\nset to \'reasonByManager\').\\n\",\"index\":[],\"name\":\"agentxSessionAdminStatus\",\"objectID\":\"1.3.6.1.2.1.74.1.3.2.1.4\",\"pid\":\"1.3.6.1.2.1.74.1.3.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The value of sysUpTime when this session was opened and,\\ntherefore, its value when this entry was added to the table.\\n\",\"index\":[],\"name\":\"agentxSessionOpenTime\",\"objectID\":\"1.3.6.1.2.1.74.1.3.2.1.5\",\"pid\":\"1.3.6.1.2.1.74.1.3.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The version of the AgentX protocol supported by the\\nsession.  This must be less than or equal to the value of\\nagentxMasterAgentXVer.\\n\",\"index\":[],\"name\":\"agentxSessionAgentXVer\",\"objectID\":\"1.3.6.1.2.1.74.1.3.2.1.6\",\"pid\":\"1.3.6.1.2.1.74.1.3.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The length of time, in seconds, that a master agent should\\nallow to elapse after dispatching a message to this session\\nbefore it regards the subagent as not responding.  This value\\nis taken from the o.timeout field of the agentx-Open-PDU.\\nThis is a session-specific value that may be overridden by\\nvalues associated with the specific registered MIB regions\\n(see agentxRegTimeout). A value of zero(0) indicates that\\nthe master agent\'s default timeout value should be used\\n\\n(see agentxDefaultTimeout).\\n\",\"index\":[],\"name\":\"agentxSessionTimeout\",\"objectID\":\"1.3.6.1.2.1.74.1.3.2.1.7\",\"pid\":\"1.3.6.1.2.1.74.1.3.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"}],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"agentxRegistration\",\"objectID\":\"1.3.6.1.2.1.74.1.4\",\"pid\":\"1.3.6.1.2.1.74.1\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The value of sysUpTime when the last row creation or deletion\\noccurred in the agentxRegistrationTable.\\n\",\"index\":[],\"name\":\"agentxRegistrationTableLastChange\",\"objectID\":\"1.3.6.1.2.1.74.1.4.1\",\"pid\":\"1.3.6.1.2.1.74.1.4\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"A table of registered regions.\\n\",\"index\":[],\"name\":\"agentxRegistrationTable\",\"objectID\":\"1.3.6.1.2.1.74.1.4.2\",\"pid\":\"1.3.6.1.2.1.74.1.4\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"Contains information for a single registered region.  An\\nentry is created when a session  successfully registers a\\nregion and is destroyed for any of three reasons: this region\\nis unregistered by the session, the session is closed,\\nor the subagent connection is closed.\\n\",\"index\":[\"1.3.6.1.2.1.74.1.2.2.1.1\",\"1.3.6.1.2.1.74.1.3.2.1.1\",\"1.3.6.1.2.1.74.1.4.2.1.1\"],\"name\":\"agentxRegistrationEntry\",\"objectID\":\"1.3.6.1.2.1.74.1.4.2.1\",\"pid\":\"1.3.6.1.2.1.74.1.4.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"agentxRegIndex uniquely identifies a registration entry.\\nThis value is constant for the lifetime of an entry.\\n\",\"index\":[],\"name\":\"agentxRegIndex\",\"objectID\":\"1.3.6.1.2.1.74.1.4.2.1.1\",\"pid\":\"1.3.6.1.2.1.74.1.4.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The context in which the session supports the objects in this\\nregion.  A zero-length context indicates the default context.\\n\",\"index\":[],\"name\":\"agentxRegContext\",\"objectID\":\"1.3.6.1.2.1.74.1.4.2.1.2\",\"pid\":\"1.3.6.1.2.1.74.1.4.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The starting OBJECT IDENTIFIER of this registration entry.  The\\nsession identified by agentxSessionIndex implements objects\\nstarting at this value (inclusive).  Note that this value could\\nidentify an object type, an object instance, or a partial object\\ninstance.\\n\",\"index\":[],\"name\":\"agentxRegStart\",\"objectID\":\"1.3.6.1.2.1.74.1.4.2.1.3\",\"pid\":\"1.3.6.1.2.1.74.1.4.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OBJECT IDENTIFIER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"agentxRegRangeSubId is used to specify the range.  This is\\ntaken from r.region_subid in the registration PDU.  If the value\\nof this object is zero, no range is specified.  If it is non-zero,\\nit identifies the `nth\' sub-identifier in r.region for which\\nthis entry\'s agentxRegUpperBound value is substituted in the\\nOID for purposes of defining the region\'s upper bound.\\n\",\"index\":[],\"name\":\"agentxRegRangeSubId\",\"objectID\":\"1.3.6.1.2.1.74.1.4.2.1.4\",\"pid\":\"1.3.6.1.2.1.74.1.4.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"agentxRegUpperBound represents the upper-bound sub-identifier in\\na registration.  This is taken from the r.upper_bound in the\\nregistration PDU.  If agentxRegRangeSubid (r.region_subid) is\\nzero, this value is also zero and is not used to define an upper\\nbound for this registration.\\n\",\"index\":[],\"name\":\"agentxRegUpperBound\",\"objectID\":\"1.3.6.1.2.1.74.1.4.2.1.5\",\"pid\":\"1.3.6.1.2.1.74.1.4.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The registration priority.  Lower values have higher priority.\\nThis value is taken from r.priority in the register PDU.\\nSessions should use the value of 127 for r.priority if a\\ndefault value is desired.\\n\",\"index\":[],\"name\":\"agentxRegPriority\",\"objectID\":\"1.3.6.1.2.1.74.1.4.2.1.6\",\"pid\":\"1.3.6.1.2.1.74.1.4.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The timeout value, in seconds, for responses to\\nrequests associated with this registered MIB region.\\nA value of zero(0) indicates the default value (indicated\\nby by agentxSessionTimeout or agentxDefaultTimeout) is to\\nbe used.  This value is taken from the r.timeout field of\\nthe agentx-Register-PDU.\\n\",\"index\":[],\"name\":\"agentxRegTimeout\",\"objectID\":\"1.3.6.1.2.1.74.1.4.2.1.7\",\"pid\":\"1.3.6.1.2.1.74.1.4.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The value of agentxRegInstance is `true\' for\\nregistrations for which the INSTANCE_REGISTRATION\\nwas set, and is `false\' for all other registrations.\\n\",\"index\":[],\"name\":\"agentxRegInstance\",\"objectID\":\"1.3.6.1.2.1.74.1.4.2.1.8\",\"pid\":\"1.3.6.1.2.1.74.1.4.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"}],\"type\":\"IDENTIFIER\"}],\"type\":\"IDENTIFIER\"},{\"access\":\"read-only\",\"description\":\"The value of agentxRegInstance is `true\' for\\nregistrations for which the INSTANCE_REGISTRATION\\nwas set, and is `false\' for all other registrations.\\n\",\"index\":[],\"name\":\"agentxConformance\",\"objectID\":\"1.3.6.1.2.1.74.2\",\"pid\":\"1.3.6.1.2.1.74\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The value of agentxRegInstance is `true\' for\\nregistrations for which the INSTANCE_REGISTRATION\\nwas set, and is `false\' for all other registrations.\\n\",\"index\":[],\"name\":\"agentxMIBGroups\",\"objectID\":\"1.3.6.1.2.1.74.2.1\",\"pid\":\"1.3.6.1.2.1.74.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The value of agentxRegInstance is `true\' for\\nregistrations for which the INSTANCE_REGISTRATION\\nwas set, and is `false\' for all other registrations.\\n\",\"index\":[],\"name\":\"agentxMIBGroup\",\"objectID\":\"1.3.6.1.2.1.74.2.1.1\",\"pid\":\"1.3.6.1.2.1.74.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"},{\"access\":\"read-only\",\"description\":\"The value of agentxRegInstance is `true\' for\\nregistrations for which the INSTANCE_REGISTRATION\\nwas set, and is `false\' for all other registrations.\\n\",\"index\":[],\"name\":\"agentxMIBCompliances\",\"objectID\":\"1.3.6.1.2.1.74.2.2\",\"pid\":\"1.3.6.1.2.1.74.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The value of agentxRegInstance is `true\' for\\nregistrations for which the INSTANCE_REGISTRATION\\nwas set, and is `false\' for all other registrations.\\n\",\"index\":[],\"name\":\"agentxMIBCompliance\",\"objectID\":\"1.3.6.1.2.1.74.2.2.1\",\"pid\":\"1.3.6.1.2.1.74.2.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"}],\"type\":\"OBJECT\"}]}');
INSERT INTO `snmp_mib` VALUES (2, 'BRIDGE-MIB', 'BRIDGE-MIB.txt', , '', '', 1, '2021-09-29 11:55:30', '{\"BRIDGE-MIB\":[{\"index\":[],\"name\":\"dot1dBridge\",\"objectID\":\"1.3.6.1.2.1.17\",\"pid\":\"1.3.6.1.2.1\",\"subTree\":[{\"index\":[],\"name\":\"dot1dNotifications\",\"objectID\":\"1.3.6.1.2.1.17.0\",\"pid\":\"1.3.6.1.2.1.17\",\"subTree\":[{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"newRoot\",\"objectID\":\"1.3.6.1.2.1.17.0.1\",\"pid\":\"1.3.6.1.2.1.17.0\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"topologyChange\",\"objectID\":\"1.3.6.1.2.1.17.0.2\",\"pid\":\"1.3.6.1.2.1.17.0\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"dot1dBase\",\"objectID\":\"1.3.6.1.2.1.17.1\",\"pid\":\"1.3.6.1.2.1.17\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The MAC address used by this bridge when it must be\\nreferred to in a unique fashion.  It is recommended\\nthat this be the numerically smallest MAC address of\\nall ports that belong to this bridge.  However, it is only\\n\\nrequired to be unique.  When concatenated with\\ndot1dStpPriority, a unique BridgeIdentifier is formed,\\nwhich is used in the Spanning Tree Protocol.\",\"index\":[],\"name\":\"dot1dBaseBridgeAddress\",\"objectID\":\"1.3.6.1.2.1.17.1.1\",\"pid\":\"1.3.6.1.2.1.17.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of ports controlled by this bridging\\nentity.\",\"index\":[],\"name\":\"dot1dBaseNumPorts\",\"objectID\":\"1.3.6.1.2.1.17.1.2\",\"pid\":\"1.3.6.1.2.1.17.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"Indicates what type of bridging this bridge can\\nperform.  If a bridge is actually performing a\\ncertain type of bridging, this will be indicated by\\nentries in the port table for the given type.\",\"index\":[],\"name\":\"dot1dBaseType\",\"objectID\":\"1.3.6.1.2.1.17.1.3\",\"pid\":\"1.3.6.1.2.1.17.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"A table that contains generic information about every\\nport that is associated with this bridge.  Transparent,\\nsource-route, and srt ports are included.\",\"index\":[],\"name\":\"dot1dBasePortTable\",\"objectID\":\"1.3.6.1.2.1.17.1.4\",\"pid\":\"1.3.6.1.2.1.17.1\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"A list of information for each port of the bridge.\",\"index\":[\"1.3.6.1.2.1.17.1.4.1.1\"],\"name\":\"dot1dBasePortEntry\",\"objectID\":\"1.3.6.1.2.1.17.1.4.1\",\"pid\":\"1.3.6.1.2.1.17.1.4\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The port number of the port for which this entry\\ncontains bridge management information.\",\"index\":[],\"name\":\"dot1dBasePort\",\"objectID\":\"1.3.6.1.2.1.17.1.4.1.1\",\"pid\":\"1.3.6.1.2.1.17.1.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The value of the instance of the ifIndex object,\\ndefined in IF-MIB, for the interface corresponding\\nto this port.\",\"index\":[],\"name\":\"dot1dBasePortIfIndex\",\"objectID\":\"1.3.6.1.2.1.17.1.4.1.2\",\"pid\":\"1.3.6.1.2.1.17.1.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"For a port that (potentially) has the same value of\\ndot1dBasePortIfIndex as another port on the same bridge.\\nThis object contains the name of an object instance\\nunique to this port.  For example, in the case where\\nmultiple ports correspond one-to-one with multiple X.25\\nvirtual circuits, this value might identify an (e.g.,\\nthe first) object instance associated with the X.25\\nvirtual circuit corresponding to this port.\\n\\nFor a port which has a unique value of\\ndot1dBasePortIfIndex, this object can have the value\\n{ 0 0 }.\",\"index\":[],\"name\":\"dot1dBasePortCircuit\",\"objectID\":\"1.3.6.1.2.1.17.1.4.1.3\",\"pid\":\"1.3.6.1.2.1.17.1.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OBJECT IDENTIFIER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of frames discarded by this port due\\nto excessive transit delay through the bridge.  It\\nis incremented by both transparent and source\\nroute bridges.\",\"index\":[],\"name\":\"dot1dBasePortDelayExceededDiscards\",\"objectID\":\"1.3.6.1.2.1.17.1.4.1.4\",\"pid\":\"1.3.6.1.2.1.17.1.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of frames discarded by this port due\\nto an excessive size.  It is incremented by both\\ntransparent and source route bridges.\",\"index\":[],\"name\":\"dot1dBasePortMtuExceededDiscards\",\"objectID\":\"1.3.6.1.2.1.17.1.4.1.5\",\"pid\":\"1.3.6.1.2.1.17.1.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"}],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"dot1dStp\",\"objectID\":\"1.3.6.1.2.1.17.2\",\"pid\":\"1.3.6.1.2.1.17\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"An indication of what version of the Spanning Tree\\nProtocol is being run.  The value \'decLb100(2)\'\\nindicates the DEC LANbridge 100 Spanning Tree protocol.\\nIEEE 802.1D implementations will return \'ieee8021d(3)\'.\\nIf future versions of the IEEE Spanning Tree Protocol\\nthat are incompatible with the current version\\nare released a new value will be defined.\",\"index\":[],\"name\":\"dot1dStpProtocolSpecification\",\"objectID\":\"1.3.6.1.2.1.17.2.1\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The value of the write-able portion of the Bridge ID\\n(i.e., the first two octets of the (8 octet long) Bridge\\nID).  The other (last) 6 octets of the Bridge ID are\\ngiven by the value of dot1dBaseBridgeAddress.\\nOn bridges supporting IEEE 802.1t or IEEE 802.1w,\\npermissible values are 0-61440, in steps of 4096.\",\"index\":[],\"name\":\"dot1dStpPriority\",\"objectID\":\"1.3.6.1.2.1.17.2.2\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The time (in hundredths of a second) since the\\nlast time a topology change was detected by the\\nbridge entity.\\nFor RSTP, this reports the time since the tcWhile\\ntimer for any port on this Bridge was nonzero.\",\"index\":[],\"name\":\"dot1dStpTimeSinceTopologyChange\",\"objectID\":\"1.3.6.1.2.1.17.2.3\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of topology changes detected by\\nthis bridge since the management entity was last\\nreset or initialized.\",\"index\":[],\"name\":\"dot1dStpTopChanges\",\"objectID\":\"1.3.6.1.2.1.17.2.4\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The bridge identifier of the root of the spanning\\ntree, as determined by the Spanning Tree Protocol,\\nas executed by this node.  This value is used as\\nthe Root Identifier parameter in all Configuration\\nBridge PDUs originated by this node.\",\"index\":[],\"name\":\"dot1dStpDesignatedRoot\",\"objectID\":\"1.3.6.1.2.1.17.2.5\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The cost of the path to the root as seen from\\nthis bridge.\",\"index\":[],\"name\":\"dot1dStpRootCost\",\"objectID\":\"1.3.6.1.2.1.17.2.6\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The port number of the port that offers the lowest\\ncost path from this bridge to the root bridge.\",\"index\":[],\"name\":\"dot1dStpRootPort\",\"objectID\":\"1.3.6.1.2.1.17.2.7\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The maximum age of Spanning Tree Protocol information\\nlearned from the network on any port before it is\\ndiscarded, in units of hundredths of a second.  This is\\nthe actual value that this bridge is currently using.\",\"index\":[],\"name\":\"dot1dStpMaxAge\",\"objectID\":\"1.3.6.1.2.1.17.2.8\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The amount of time between the transmission of\\nConfiguration bridge PDUs by this node on any port when\\nit is the root of the spanning tree, or trying to become\\nso, in units of hundredths of a second.  This is the\\nactual value that this bridge is currently using.\",\"index\":[],\"name\":\"dot1dStpHelloTime\",\"objectID\":\"1.3.6.1.2.1.17.2.9\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"This time value determines the interval length\\nduring which no more than two Configuration bridge\\nPDUs shall be transmitted by this node, in units\\nof hundredths of a second.\",\"index\":[],\"name\":\"dot1dStpHoldTime\",\"objectID\":\"1.3.6.1.2.1.17.2.10\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"This time value, measured in units of hundredths of a\\nsecond, controls how fast a port changes its spanning\\nstate when moving towards the Forwarding state.  The\\nvalue determines how long the port stays in each of the\\nListening and Learning states, which precede the\\nForwarding state.  This value is also used when a\\ntopology change has been detected and is underway, to\\nage all dynamic entries in the Forwarding Database.\\n[Note that this value is the one that this bridge is\\ncurrently using, in contrast to\\ndot1dStpBridgeForwardDelay, which is the value that this\\nbridge and all others would start using if/when this\\nbridge were to become the root.]\",\"index\":[],\"name\":\"dot1dStpForwardDelay\",\"objectID\":\"1.3.6.1.2.1.17.2.11\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The value that all bridges use for MaxAge when this\\nbridge is acting as the root.  Note that 802.1D-1998\\nspecifies that the range for this parameter is related\\nto the value of dot1dStpBridgeHelloTime.  The\\ngranularity of this timer is specified by 802.1D-1998 to\\nbe 1 second.  An agent may return a badValue error if a\\nset is attempted to a value that is not a whole number\\nof seconds.\",\"index\":[],\"name\":\"dot1dStpBridgeMaxAge\",\"objectID\":\"1.3.6.1.2.1.17.2.12\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The value that all bridges use for HelloTime when this\\nbridge is acting as the root.  The granularity of this\\ntimer is specified by 802.1D-1998 to be 1 second.  An\\nagent may return a badValue error if a set is attempted\\n\\nto a value that is not a whole number of seconds.\",\"index\":[],\"name\":\"dot1dStpBridgeHelloTime\",\"objectID\":\"1.3.6.1.2.1.17.2.13\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The value that all bridges use for ForwardDelay when\\nthis bridge is acting as the root.  Note that\\n802.1D-1998 specifies that the range for this parameter\\nis related to the value of dot1dStpBridgeMaxAge.  The\\ngranularity of this timer is specified by 802.1D-1998 to\\nbe 1 second.  An agent may return a badValue error if a\\nset is attempted to a value that is not a whole number\\nof seconds.\",\"index\":[],\"name\":\"dot1dStpBridgeForwardDelay\",\"objectID\":\"1.3.6.1.2.1.17.2.14\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"A table that contains port-specific information\\nfor the Spanning Tree Protocol.\",\"index\":[],\"name\":\"dot1dStpPortTable\",\"objectID\":\"1.3.6.1.2.1.17.2.15\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"A list of information maintained by every port about\\nthe Spanning Tree Protocol state for that port.\",\"index\":[\"1.3.6.1.2.1.17.2.15.1.1\"],\"name\":\"dot1dStpPortEntry\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1\",\"pid\":\"1.3.6.1.2.1.17.2.15\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The port number of the port for which this entry\\ncontains Spanning Tree Protocol management information.\",\"index\":[],\"name\":\"dot1dStpPort\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1.1\",\"pid\":\"1.3.6.1.2.1.17.2.15.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The value of the priority field that is contained in\\nthe first (in network byte order) octet of the (2 octet\\nlong) Port ID.  The other octet of the Port ID is given\\nby the value of dot1dStpPort.\\nOn bridges supporting IEEE 802.1t or IEEE 802.1w,\\npermissible values are 0-240, in steps of 16.\",\"index\":[],\"name\":\"dot1dStpPortPriority\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1.2\",\"pid\":\"1.3.6.1.2.1.17.2.15.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The port\'s current state, as defined by application of\\nthe Spanning Tree Protocol.  This state controls what\\naction a port takes on reception of a frame.  If the\\nbridge has detected a port that is malfunctioning, it\\nwill place that port into the broken(6) state.  For\\nports that are disabled (see dot1dStpPortEnable), this\\nobject will have a value of disabled(1).\",\"index\":[],\"name\":\"dot1dStpPortState\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1.3\",\"pid\":\"1.3.6.1.2.1.17.2.15.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The enabled/disabled status of the port.\",\"index\":[],\"name\":\"dot1dStpPortEnable\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1.4\",\"pid\":\"1.3.6.1.2.1.17.2.15.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The contribution of this port to the path cost of\\npaths towards the spanning tree root which include\\nthis port.  802.1D-1998 recommends that the default\\nvalue of this parameter be in inverse proportion to\\n\\nthe speed of the attached LAN.\\n\\nNew implementations should support dot1dStpPortPathCost32.\\nIf the port path costs exceeds the maximum value of this\\nobject then this object should report the maximum value,\\nnamely 65535.  Applications should try to read the\\ndot1dStpPortPathCost32 object if this object reports\\nthe maximum value.\",\"index\":[],\"name\":\"dot1dStpPortPathCost\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1.5\",\"pid\":\"1.3.6.1.2.1.17.2.15.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The unique Bridge Identifier of the Bridge\\nrecorded as the Root in the Configuration BPDUs\\ntransmitted by the Designated Bridge for the\\nsegment to which the port is attached.\",\"index\":[],\"name\":\"dot1dStpPortDesignatedRoot\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1.6\",\"pid\":\"1.3.6.1.2.1.17.2.15.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The path cost of the Designated Port of the segment\\nconnected to this port.  This value is compared to the\\nRoot Path Cost field in received bridge PDUs.\",\"index\":[],\"name\":\"dot1dStpPortDesignatedCost\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1.7\",\"pid\":\"1.3.6.1.2.1.17.2.15.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The Bridge Identifier of the bridge that this\\nport considers to be the Designated Bridge for\\nthis port\'s segment.\",\"index\":[],\"name\":\"dot1dStpPortDesignatedBridge\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1.8\",\"pid\":\"1.3.6.1.2.1.17.2.15.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The Port Identifier of the port on the Designated\\nBridge for this port\'s segment.\",\"index\":[],\"name\":\"dot1dStpPortDesignatedPort\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1.9\",\"pid\":\"1.3.6.1.2.1.17.2.15.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of times this port has transitioned\\nfrom the Learning state to the Forwarding state.\",\"index\":[],\"name\":\"dot1dStpPortForwardTransitions\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1.10\",\"pid\":\"1.3.6.1.2.1.17.2.15.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The contribution of this port to the path cost of\\npaths towards the spanning tree root which include\\nthis port.  802.1D-1998 recommends that the default\\nvalue of this parameter be in inverse proportion to\\nthe speed of the attached LAN.\\n\\nThis object replaces dot1dStpPortPathCost to support\\nIEEE 802.1t.\",\"index\":[],\"name\":\"dot1dStpPortPathCost32\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1.11\",\"pid\":\"1.3.6.1.2.1.17.2.15.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"}],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"dot1dSr\",\"objectID\":\"1.3.6.1.2.1.17.3\",\"pid\":\"1.3.6.1.2.1.17\",\"subTree\":[],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"dot1dTp\",\"objectID\":\"1.3.6.1.2.1.17.4\",\"pid\":\"1.3.6.1.2.1.17\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The total number of Forwarding Database entries that\\nhave been or would have been learned, but have been\\ndiscarded due to a lack of storage space in the\\nForwarding Database.  If this counter is increasing, it\\nindicates that the Forwarding Database is regularly\\nbecoming full (a condition that has unpleasant\\nperformance effects on the subnetwork).  If this counter\\nhas a significant value but is not presently increasing,\\nit indicates that the problem has been occurring but is\\nnot persistent.\",\"index\":[],\"name\":\"dot1dTpLearnedEntryDiscards\",\"objectID\":\"1.3.6.1.2.1.17.4.1\",\"pid\":\"1.3.6.1.2.1.17.4\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The timeout period in seconds for aging out\\ndynamically-learned forwarding information.\\n802.1D-1998 recommends a default of 300 seconds.\",\"index\":[],\"name\":\"dot1dTpAgingTime\",\"objectID\":\"1.3.6.1.2.1.17.4.2\",\"pid\":\"1.3.6.1.2.1.17.4\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"A table that contains information about unicast\\nentries for which the bridge has forwarding and/or\\nfiltering information.  This information is used\\nby the transparent bridging function in\\ndetermining how to propagate a received frame.\",\"index\":[],\"name\":\"dot1dTpFdbTable\",\"objectID\":\"1.3.6.1.2.1.17.4.3\",\"pid\":\"1.3.6.1.2.1.17.4\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"Information about a specific unicast MAC address\\nfor which the bridge has some forwarding and/or\\nfiltering information.\",\"index\":[\"1.3.6.1.2.1.17.4.3.1.1\"],\"name\":\"dot1dTpFdbEntry\",\"objectID\":\"1.3.6.1.2.1.17.4.3.1\",\"pid\":\"1.3.6.1.2.1.17.4.3\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"A unicast MAC address for which the bridge has\\nforwarding and/or filtering information.\",\"index\":[],\"name\":\"dot1dTpFdbAddress\",\"objectID\":\"1.3.6.1.2.1.17.4.3.1.1\",\"pid\":\"1.3.6.1.2.1.17.4.3.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"Either the value \'0\', or the port number of the port on\\nwhich a frame having a source address equal to the value\\nof the corresponding instance of dot1dTpFdbAddress has\\nbeen seen.  A value of \'0\' indicates that the port\\nnumber has not been learned, but that the bridge does\\nhave some forwarding/filtering information about this\\naddress (e.g., in the dot1dStaticTable).  Implementors\\nare encouraged to assign the port value to this object\\nwhenever it is learned, even for addresses for which the\\ncorresponding value of dot1dTpFdbStatus is not\\nlearned(3).\",\"index\":[],\"name\":\"dot1dTpFdbPort\",\"objectID\":\"1.3.6.1.2.1.17.4.3.1.2\",\"pid\":\"1.3.6.1.2.1.17.4.3.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The status of this entry.  The meanings of the\\nvalues are:\\n    other(1) - none of the following.  This would\\n        include the case where some other MIB object\\n        (not the corresponding instance of\\n        dot1dTpFdbPort, nor an entry in the\\n        dot1dStaticTable) is being used to determine if\\n        and how frames addressed to the value of the\\n        corresponding instance of dot1dTpFdbAddress are\\n        being forwarded.\\n    invalid(2) - this entry is no longer valid (e.g.,\\n        it was learned but has since aged out), but has\\n        not yet been flushed from the table.\\n    learned(3) - the value of the corresponding instance\\n        of dot1dTpFdbPort was learned, and is being\\n        used.\\n    self(4) - the value of the corresponding instance of\\n        dot1dTpFdbAddress represents one of the bridge\'s\\n        addresses.  The corresponding instance of\\n        dot1dTpFdbPort indicates which of the bridge\'s\\n        ports has this address.\\n    mgmt(5) - the value of the corresponding instance of\\n        dot1dTpFdbAddress is also the value of an\\n        existing instance of dot1dStaticAddress.\",\"index\":[],\"name\":\"dot1dTpFdbStatus\",\"objectID\":\"1.3.6.1.2.1.17.4.3.1.3\",\"pid\":\"1.3.6.1.2.1.17.4.3.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"},{\"access\":\"not-accessible\",\"description\":\"A table that contains information about every port that\\nis associated with this transparent bridge.\",\"index\":[],\"name\":\"dot1dTpPortTable\",\"objectID\":\"1.3.6.1.2.1.17.4.4\",\"pid\":\"1.3.6.1.2.1.17.4\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"A list of information for each port of a transparent\\nbridge.\",\"index\":[\"1.3.6.1.2.1.17.4.4.1.1\"],\"name\":\"dot1dTpPortEntry\",\"objectID\":\"1.3.6.1.2.1.17.4.4.1\",\"pid\":\"1.3.6.1.2.1.17.4.4\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The port number of the port for which this entry\\ncontains Transparent bridging management information.\",\"index\":[],\"name\":\"dot1dTpPort\",\"objectID\":\"1.3.6.1.2.1.17.4.4.1.1\",\"pid\":\"1.3.6.1.2.1.17.4.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The maximum size of the INFO (non-MAC) field that\\n\\nthis port will receive or transmit.\",\"index\":[],\"name\":\"dot1dTpPortMaxInfo\",\"objectID\":\"1.3.6.1.2.1.17.4.4.1.2\",\"pid\":\"1.3.6.1.2.1.17.4.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of frames that have been received by this\\nport from its segment.  Note that a frame received on the\\ninterface corresponding to this port is only counted by\\nthis object if and only if it is for a protocol being\\nprocessed by the local bridging function, including\\nbridge management frames.\",\"index\":[],\"name\":\"dot1dTpPortInFrames\",\"objectID\":\"1.3.6.1.2.1.17.4.4.1.3\",\"pid\":\"1.3.6.1.2.1.17.4.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of frames that have been transmitted by this\\nport to its segment.  Note that a frame transmitted on\\nthe interface corresponding to this port is only counted\\nby this object if and only if it is for a protocol being\\nprocessed by the local bridging function, including\\nbridge management frames.\",\"index\":[],\"name\":\"dot1dTpPortOutFrames\",\"objectID\":\"1.3.6.1.2.1.17.4.4.1.4\",\"pid\":\"1.3.6.1.2.1.17.4.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"Count of received valid frames that were discarded\\n(i.e., filtered) by the Forwarding Process.\",\"index\":[],\"name\":\"dot1dTpPortInDiscards\",\"objectID\":\"1.3.6.1.2.1.17.4.4.1.5\",\"pid\":\"1.3.6.1.2.1.17.4.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"}],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"dot1dStatic\",\"objectID\":\"1.3.6.1.2.1.17.5\",\"pid\":\"1.3.6.1.2.1.17\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"A table containing filtering information configured\\ninto the bridge by (local or network) management\\nspecifying the set of ports to which frames received\\nfrom specific ports and containing specific destination\\naddresses are allowed to be forwarded.  The value of\\nzero in this table, as the port number from which frames\\nwith a specific destination address are received, is\\nused to specify all ports for which there is no specific\\nentry in this table for that particular destination\\naddress.  Entries are valid for unicast and for\\ngroup/broadcast addresses.\",\"index\":[],\"name\":\"dot1dStaticTable\",\"objectID\":\"1.3.6.1.2.1.17.5.1\",\"pid\":\"1.3.6.1.2.1.17.5\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"Filtering information configured into the bridge by\\n(local or network) management specifying the set of\\nports to which frames received from a specific port and\\ncontaining a specific destination address are allowed to\\nbe forwarded.\",\"index\":[\"1.3.6.1.2.1.17.5.1.1.1\",\"1.3.6.1.2.1.17.5.1.1.2\"],\"name\":\"dot1dStaticEntry\",\"objectID\":\"1.3.6.1.2.1.17.5.1.1\",\"pid\":\"1.3.6.1.2.1.17.5.1\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-create\",\"description\":\"The destination MAC address in a frame to which this\\nentry\'s filtering information applies.  This object can\\ntake the value of a unicast address, a group address, or\\nthe broadcast address.\",\"index\":[],\"name\":\"dot1dStaticAddress\",\"objectID\":\"1.3.6.1.2.1.17.5.1.1.1\",\"pid\":\"1.3.6.1.2.1.17.5.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"Either the value \'0\', or the port number of the port\\nfrom which a frame must be received in order for this\\nentry\'s filtering information to apply.  A value of zero\\nindicates that this entry applies on all ports of the\\nbridge for which there is no other applicable entry.\",\"index\":[],\"name\":\"dot1dStaticReceivePort\",\"objectID\":\"1.3.6.1.2.1.17.5.1.1.2\",\"pid\":\"1.3.6.1.2.1.17.5.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The set of ports to which frames received from a\\nspecific port and destined for a specific MAC address,\\nare allowed to be forwarded.  Each octet within the\\nvalue of this object specifies a set of eight ports,\\nwith the first octet specifying ports 1 through 8, the\\nsecond octet specifying ports 9 through 16, etc.  Within\\neach octet, the most significant bit represents the\\nlowest numbered port, and the least significant bit\\nrepresents the highest numbered port.  Thus, each port\\nof the bridge is represented by a single bit within the\\nvalue of this object.  If that bit has a value of \'1\',\\nthen that port is included in the set of ports; the port\\nis not included if its bit has a value of \'0\'.  (Note\\nthat the setting of the bit corresponding to the port\\nfrom which a frame is received is irrelevant.)  The\\ndefault value of this object is a string of ones of\\nappropriate length.\\n\\nThe value of this object may exceed the required minimum\\nmaximum message size of some SNMP transport (484 bytes,\\nin the case of SNMP over UDP, see RFC 3417, section 3.2).\\nSNMP engines on bridges supporting a large number of\\nports must support appropriate maximum message sizes.\",\"index\":[],\"name\":\"dot1dStaticAllowedToGoTo\",\"objectID\":\"1.3.6.1.2.1.17.5.1.1.3\",\"pid\":\"1.3.6.1.2.1.17.5.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"dot1dStaticStatus\",\"objectID\":\"1.3.6.1.2.1.17.5.1.1.4\",\"pid\":\"1.3.6.1.2.1.17.5.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"}],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"dot1dConformance\",\"objectID\":\"1.3.6.1.2.1.17.8\",\"pid\":\"1.3.6.1.2.1.17\",\"subTree\":[{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"dot1dGroups\",\"objectID\":\"1.3.6.1.2.1.17.8.1\",\"pid\":\"1.3.6.1.2.1.17.8\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"dot1dBaseBridgeGroup\",\"objectID\":\"1.3.6.1.2.1.17.8.1.1\",\"pid\":\"1.3.6.1.2.1.17.8.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"dot1dBasePortGroup\",\"objectID\":\"1.3.6.1.2.1.17.8.1.2\",\"pid\":\"1.3.6.1.2.1.17.8.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain 