INSERT INTO `snmp_mib` VALUES (15, 'IF-INVERTED-STACK-MIB', 'IF-INVERTED-STACK-MIB.txt', , '', '', 1, '2021-09-29 11:57:35', '{\"IF-INVERTED-STACK-MIB\":[{\"index\":[],\"name\":\"ifInvertedStackMIB\",\"objectID\":\"1.3.6.1.2.1.77\",\"pid\":\"1.3.6.1.2.1\",\"subTree\":[{\"index\":[],\"name\":\"ifInvMIBObjects\",\"objectID\":\"1.3.6.1.2.1.77.1\",\"pid\":\"1.3.6.1.2.1.77\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"A table containing information on the relationships between\\n\\nthe multiple sub-layers of network interfaces.  In\\nparticular, it contains information on which sub-layers run\\n\'underneath\' which other sub-layers, where each sub-layer\\ncorresponds to a conceptual row in the ifTable.  For\\nexample, when the sub-layer with ifIndex value x runs\\nunderneath the sub-layer with ifIndex value y, then this\\ntable contains:\\n\\n  ifInvStackStatus.x.y=active\\n\\nFor each ifIndex value, z, which identifies an active\\ninterface, there are always at least two instantiated rows\\nin this table associated with z.  For one of these rows, z\\nis the value of ifStackHigherLayer; for the other, z is the\\nvalue of ifStackLowerLayer.  (If z is not involved in\\nmultiplexing, then these are the only two rows associated\\nwith z.)\\n\\nFor example, two rows exist even for an interface which has\\nno others stacked on top or below it:\\n\\n  ifInvStackStatus.z.0=active\\n  ifInvStackStatus.0.z=active\\n\\nThis table contains exactly the same number of rows as the\\nifStackTable, but the rows appear in a different order.\",\"index\":[],\"name\":\"ifInvStackTable\",\"objectID\":\"1.3.6.1.2.1.77.1.1\",\"pid\":\"1.3.6.1.2.1.77.1\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"Information on a particular relationship between two sub-\\nlayers, specifying that one sub-layer runs underneath the\\nother sub-layer.  Each sub-layer corresponds to a conceptual\\nrow in the ifTable.\",\"index\":[\"1.3.6.1.2.1.31.1.2.1.2\",\"1.3.6.1.2.1.31.1.2.1.1\"],\"name\":\"ifInvStackEntry\",\"objectID\":\"1.3.6.1.2.1.77.1.1.1\",\"pid\":\"1.3.6.1.2.1.77.1.1\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The status of the relationship between two sub-layers.\\n\\nAn instance of this object exists for each instance of the\\nifStackStatus object, and vice versa.  For example, if the\\nvariable ifStackStatus.H.L exists, then the variable\\nifInvStackStatus.L.H must also exist, and vice versa.  In\\naddition, the two variables always have the same value.\\n\\nHowever, unlike ifStackStatus, the ifInvStackStatus object\\nis NOT write-able.  A network management application wishing\\nto change a relationship between sub-layers H and L cannot\\ndo so by modifying the value of ifInvStackStatus.L.H, but\\nmust instead modify the value of ifStackStatus.H.L.  After\\nthe ifStackTable is modified, the change will be reflected\\nin this table.\",\"index\":[],\"name\":\"ifInvStackStatus\",\"objectID\":\"1.3.6.1.2.1.77.1.1.1.1\",\"pid\":\"1.3.6.1.2.1.77.1.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"},{\"access\":\"read-only\",\"description\":\"The status of the relationship between two sub-layers.\\n\\nAn instance of this object exists for each instance of the\\nifStackStatus object, and vice versa.  For example, if the\\nvariable ifStackStatus.H.L exists, then the variable\\nifInvStackStatus.L.H must also exist, and vice versa.  In\\naddition, the two variables always have the same value.\\n\\nHowever, unlike ifStackStatus, the ifInvStackStatus object\\nis NOT write-able.  A network management application wishing\\nto change a relationship between sub-layers H and L cannot\\ndo so by modifying the value of ifInvStackStatus.L.H, but\\nmust instead modify the value of ifStackStatus.H.L.  After\\nthe ifStackTable is modified, the change will be reflected\\nin this table.\",\"index\":[],\"name\":\"ifInvConformance\",\"objectID\":\"1.3.6.1.2.1.77.1.2\",\"pid\":\"1.3.6.1.2.1.77.1\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The status of the relationship between two sub-layers.\\n\\nAn instance of this object exists for each instance of the\\nifStackStatus object, and vice versa.  For example, if the\\nvariable ifStackStatus.H.L exists, then the variable\\nifInvStackStatus.L.H must also exist, and vice versa.  In\\naddition, the two variables always have the same value.\\n\\nHowever, unlike ifStackStatus, the ifInvStackStatus object\\nis NOT write-able.  A network management application wishing\\nto change a relationship between sub-layers H and L cannot\\ndo so by modifying the value of ifInvStackStatus.L.H, but\\nmust instead modify the value of ifStackStatus.H.L.  After\\nthe ifStackTable is modified, the change will be reflected\\nin this table.\",\"index\":[],\"name\":\"ifInvGroups\",\"objectID\":\"1.3.6.1.2.1.77.1.2.1\",\"pid\":\"1.3.6.1.2.1.77.1.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The status of the relationship between two sub-layers.\\n\\nAn instance of this object exists for each instance of the\\nifStackStatus object, and vice versa.  For example, if the\\nvariable ifStackStatus.H.L exists, then the variable\\nifInvStackStatus.L.H must also exist, and vice versa.  In\\naddition, the two variables always have the same value.\\n\\nHowever, unlike ifStackStatus, the ifInvStackStatus object\\nis NOT write-able.  A network management application wishing\\nto change a relationship between sub-layers H and L cannot\\ndo so by modifying the value of ifInvStackStatus.L.H, but\\nmust instead modify the value of ifStackStatus.H.L.  After\\nthe ifStackTable is modified, the change will be reflected\\nin this table.\",\"index\":[],\"name\":\"ifInvStackGroup\",\"objectID\":\"1.3.6.1.2.1.77.1.2.1.1\",\"pid\":\"1.3.6.1.2.1.77.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"},{\"access\":\"read-only\",\"description\":\"The status of the relationship between two sub-layers.\\n\\nAn instance of this object exists for each instance of the\\nifStackStatus object, and vice versa.  For example, if the\\nvariable ifStackStatus.H.L exists, then the variable\\nifInvStackStatus.L.H must also exist, and vice versa.  In\\naddition, the two variables always have the same value.\\n\\nHowever, unlike ifStackStatus, the ifInvStackStatus object\\nis NOT write-able.  A network management application wishing\\nto change a relationship between sub-layers H and L cannot\\ndo so by modifying the value of ifInvStackStatus.L.H, but\\nmust instead modify the value of ifStackStatus.H.L.  After\\nthe ifStackTable is modified, the change will be reflected\\nin this table.\",\"index\":[],\"name\":\"ifInvCompliances\",\"objectID\":\"1.3.6.1.2.1.77.1.2.2\",\"pid\":\"1.3.6.1.2.1.77.1.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The status of the relationship between two sub-layers.\\n\\nAn instance of this object exists for each instance of the\\nifStackStatus object, and vice versa.  For example, if the\\nvariable ifStackStatus.H.L exists, then the variable\\nifInvStackStatus.L.H must also exist, and vice versa.  In\\naddition, the two variables always have the same value.\\n\\nHowever, unlike ifStackStatus, the ifInvStackStatus object\\nis NOT write-able.  A network management application wishing\\nto change a relationship between sub-layers H and L cannot\\ndo so by modifying the value of ifInvStackStatus.L.H, but\\nmust instead modify the value of ifStackStatus.H.L.  After\\nthe ifStackTable is modified, the change will be reflected\\nin this table.\",\"index\":[],\"name\":\"ifInvCompliance\",\"objectID\":\"1.3.6.1.2.1.77.1.2.2.1\",\"pid\":\"1.3.6.1.2.1.77.1.2.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"}],\"type\":\"IDENTIFIER\"}],\"type\":\"OBJECT\"}]}');
INSERT INTO `snmp_mib` VALUES (16, 'IF-MIB', 'IF-MIB.txt', , '', '', 1, '2021-09-29 11:57:42', '{\"IF-MIB\":[{\"index\":[],\"name\":\"ifMIB\",\"objectID\":\"1.3.6.1.2.1.31\",\"pid\":\"1.3.6.1.2.1\",\"subTree\":[{\"index\":[],\"name\":\"ifMIBObjects\",\"objectID\":\"1.3.6.1.2.1.31.1\",\"pid\":\"1.3.6.1.2.1.31\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The value of sysUpTime at the time of the last creation or\\ndeletion of an entry in the ifTable.  If the number of\\nentries has been unchanged since the last re-initialization\\nof the local network management subsystem, then this object\\ncontains a zero value.\",\"index\":[],\"name\":\"ifTableLastChange\",\"objectID\":\"1.3.6.1.2.1.31.1.5\",\"pid\":\"1.3.6.1.2.1.31.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"A list of interface entries.  The number of entries is\\ngiven by the value of ifNumber.  This table contains\\nadditional objects for the interface table.\",\"index\":[],\"name\":\"ifXTable\",\"objectID\":\"1.3.6.1.2.1.31.1.1\",\"pid\":\"1.3.6.1.2.1.31.1\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"An entry containing additional management information\\napplicable to a particular interface.\",\"index\":[],\"name\":\"ifXEntry\",\"objectID\":\"1.3.6.1.2.1.31.1.1.1\",\"pid\":\"1.3.6.1.2.1.31.1.1\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The textual name of the interface.  The value of this\\nobject should be the name of the interface as assigned by\\nthe local device and should be suitable for use in commands\\nentered at the device\'s `console\'.  This might be a text\\nname, such as `le0\' or a simple port number, such as `1\',\\ndepending on the interface naming syntax of the device.  If\\nseveral entries in the ifTable together represent a single\\ninterface as named by the device, then each will have the\\nsame value of ifName.  Note that for an agent which responds\\nto SNMP queries concerning an interface on some other\\n(proxied) device, then the value of ifName for such an\\ninterface is the proxied device\'s local name for it.\\n\\nIf there is no local name, or this object is otherwise not\\napplicable, then this object contains a zero-length string.\",\"index\":[],\"name\":\"ifName\",\"objectID\":\"1.3.6.1.2.1.31.1.1.1.1\",\"pid\":\"1.3.6.1.2.1.31.1.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of packets, delivered by this sub-layer to a\\nhigher (sub-)layer, which were addressed to a multicast\\naddress at this sub-layer.  For a MAC layer protocol, this\\nincludes both Group and Functional addresses.\\n\\nDiscontinuities in the value of this counter can occur at\\nre-initialization of the management system, and at other\\n\\ntimes as indicated by the value of\\nifCounterDiscontinuityTime.\",\"index\":[],\"name\":\"ifInMulticastPkts\",\"objectID\":\"1.3.6.1.2.1.31.1.1.1.2\",\"pid\":\"1.3.6.1.2.1.31.1.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of packets, delivered by this sub-layer to a\\nhigher (sub-)layer, which were addressed to a broadcast\\naddress at this sub-layer.\\n\\nDiscontinuities in the value of this counter can occur at\\nre-initialization of the management system, and at other\\ntimes as indicated by the value of\\nifCounterDiscontinuityTime.\",\"index\":[],\"name\":\"ifInBroadcastPkts\",\"objectID\":\"1.3.6.1.2.1.31.1.1.1.3\",\"pid\":\"1.3.6.1.2.1.31.1.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of packets that higher-level protocols\\nrequested be transmitted, and which were addressed to a\\nmulticast address at this sub-layer, including those that\\nwere discarded or not sent.  For a MAC layer protocol, this\\nincludes both Group and Functional addresses.\\n\\nDiscontinuities in the value of this counter can occur at\\nre-initialization of the management system, and at other\\ntimes as indicated by the value of\\nifCounterDiscontinuityTime.\",\"index\":[],\"name\":\"ifOutMulticastPkts\",\"objectID\":\"1.3.6.1.2.1.31.1.1.1.4\",\"pid\":\"1.3.6.1.2.1.31.1.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of packets that higher-level protocols\\nrequested be transmitted, and which were addressed to a\\nbroadcast address at this sub-layer, including those that\\nwere discarded or not sent.\\n\\nDiscontinuities in the value of this counter can occur at\\nre-initialization of the management system, and at other\\n\\ntimes as indicated by the value of\\nifCounterDiscontinuityTime.\",\"index\":[],\"name\":\"ifOutBroadcastPkts\",\"objectID\":\"1.3.6.1.2.1.31.1.1.1.5\",\"pid\":\"1.3.6.1.2.1.31.1.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of octets received on the interface,\\nincluding framing characters.  This object is a 64-bit\\nversion of ifInOctets.\\n\\nDiscontinuities in the value of this counter can occur at\\nre-initialization of the management system, and at other\\ntimes as indicated by the value of\\nifCounterDiscontinuityTime.\",\"index\":[],\"name\":\"ifHCInOctets\",\"objectID\":\"1.3.6.1.2.1.31.1.1.1.6\",\"pid\":\"1.3.6.1.2.1.31.1.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of packets, delivered by this sub-layer to a\\nhigher (sub-)layer, which were not addressed to a multicast\\nor broadcast address at this sub-layer.  This object is a\\n64-bit version of ifInUcastPkts.\\n\\nDiscontinuities in the value of this counter can occur at\\nre-initialization of the management system, and at other\\ntimes as indicated by the value of\\nifCounterDiscontinuityTime.\",\"index\":[],\"name\":\"ifHCInUcastPkts\",\"objectID\":\"1.3.6.1.2.1.31.1.1.1.7\",\"pid\":\"1.3.6.1.2.1.31.1.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of packets, delivered by this sub-layer to a\\nhigher (sub-)layer, which were addressed to a multicast\\naddress at this sub-layer.  For a MAC layer protocol, this\\nincludes both Group and Functional addresses.  This object\\nis a 64-bit version of ifInMulticastPkts.\\n\\nDiscontinuities in the value of this counter can occur at\\nre-initialization of the management system, and at other\\ntimes as indicated by the value of\\nifCounterDiscontinuityTime.\",\"index\":[],\"name\":\"ifHCInMulticastPkts\",\"objectID\":\"1.3.6.1.2.1.31.1.1.1.8\",\"pid\":\"1.3.6.1.2.1.31.1.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of packets, delivered by this sub-layer to a\\nhigher (sub-)layer, which were addressed to a broadcast\\naddress at this sub-layer.  This object is a 64-bit version\\nof ifInBroadcastPkts.\\n\\nDiscontinuities in the value of this counter can occur at\\nre-initialization of the management system, and at other\\ntimes as indicated by the value of\\nifCounterDiscontinuityTime.\",\"index\":[],\"name\":\"ifHCInBroadcastPkts\",\"objectID\":\"1.3.6.1.2.1.31.1.1.1.9\",\"pid\":\"1.3.6.1.2.1.31.1.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of octets transmitted out of the\\ninterface, including framing characters.  This object is a\\n64-bit version of ifOutOctets.\\n\\nDiscontinuities in the value of this counter can occur at\\nre-initialization of the management system, and at other\\ntimes as indicated by the value of\\nifCounterDiscontinuityTime.\",\"index\":[],\"name\":\"ifHCOutOctets\",\"objectID\":\"1.3.6.1.2.1.31.1.1.1.10\",\"pid\":\"1.3.6.1.2.1.31.1.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of packets that higher-level protocols\\nrequested be transmitted, and which were not addressed to a\\nmulticast or broadcast address at this sub-layer, including\\nthose that were discarded or not sent.  This object is a\\n64-bit version of ifOutUcastPkts.\\n\\nDiscontinuities in the value of this counter can occur at\\nre-initialization of the management system, and at other\\ntimes as indicated by the value of\\nifCounterDiscontinuityTime.\",\"index\":[],\"name\":\"ifHCOutUcastPkts\",\"objectID\":\"1.3.6.1.2.1.31.1.1.1.11\",\"pid\":\"1.3.6.1.2.1.31.1.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of packets that higher-level protocols\\nrequested be transmitted, and which were addressed to a\\nmulticast address at this sub-layer, including those that\\nwere discarded or not sent.  For a MAC layer protocol, this\\nincludes both Group and Functional addresses.  This object\\nis a 64-bit version of ifOutMulticastPkts.\\n\\nDiscontinuities in the value of this counter can occur at\\nre-initialization of the management system, and at other\\ntimes as indicated by the value of\\nifCounterDiscontinuityTime.\",\"index\":[],\"name\":\"ifHCOutMulticastPkts\",\"objectID\":\"1.3.6.1.2.1.31.1.1.1.12\",\"pid\":\"1.3.6.1.2.1.31.1.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of packets that higher-level protocols\\nrequested be transmitted, and which were addressed to a\\nbroadcast address at this sub-layer, including those that\\nwere discarded or not sent.  This object is a 64-bit version\\nof ifOutBroadcastPkts.\\n\\nDiscontinuities in the value of this counter can occur at\\nre-initialization of the management system, and at other\\ntimes as indicated by the value of\\nifCounterDiscontinuityTime.\",\"index\":[],\"name\":\"ifHCOutBroadcastPkts\",\"objectID\":\"1.3.6.1.2.1.31.1.1.1.13\",\"pid\":\"1.3.6.1.2.1.31.1.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"Indicates whether linkUp/linkDown traps should be generated\\nfor this interface.\\n\\nBy default, this object should have the value enabled(1) for\\ninterfaces which do not operate on \'top\' of any other\\ninterface (as defined in the ifStackTable), and disabled(2)\\notherwise.\",\"index\":[],\"name\":\"ifLinkUpDownTrapEnable\",\"objectID\":\"1.3.6.1.2.1.31.1.1.1.14\",\"pid\":\"1.3.6.1.2.1.31.1.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"An estimate of the interface\'s current bandwidth in units\\nof 1,000,000 bits per second.  If this object reports a\\nvalue of `n\' then the speed of the interface is somewhere in\\nthe range of `n-500,000\' to `n+499,999\'.  For interfaces\\nwhich do not vary in bandwidth or for those where no\\naccurate estimation can be made, this object should contain\\nthe nominal bandwidth.  For a sub-layer which has no concept\\nof bandwidth, this object should be zero.\",\"index\":[],\"name\":\"ifHighSpeed\",\"objectID\":\"1.3.6.1.2.1.31.1.1.1.15\",\"pid\":\"1.3.6.1.2.1.31.1.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"This object has a value of false(2) if this interface only\\naccepts packets/frames that are addressed to this station.\\nThis object has a value of true(1) when the station accepts\\nall packets/frames transmitted on the media.  The value\\ntrue(1) is only legal on certain types of media.  If legal,\\nsetting this object to a value of true(1) may require the\\ninterface to be reset before becoming effective.\\n\\nThe value of ifPromiscuousMode does not affect the reception\\nof broadcast and multicast packets/frames by the interface.\",\"index\":[],\"name\":\"ifPromiscuousMode\",\"objectID\":\"1.3.6.1.2.1.31.1.1.1.16\",\"pid\":\"1.3.6.1.2.1.31.1.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"This object has the value \'true(1)\' if the interface\\nsublayer has a physical connector and the value \'false(2)\'\\notherwise.\",\"index\":[],\"name\":\"ifConnectorPresent\",\"objectID\":\"1.3.6.1.2.1.31.1.1.1.17\",\"pid\":\"1.3.6.1.2.1.31.1.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"This object is an \'alias\' name for the interface as\\nspecified by a network manager, and provides a non-volatile\\n\'handle\' for the interface.\\n\\nOn the first instantiation of an interface, the value of\\nifAlias associated with that interface is the zero-length\\nstring.  As and when a value is written into an instance of\\nifAlias through a network management set operation, then the\\nagent must retain the supplied value in the ifAlias instance\\nassociated with the same interface for as long as that\\ninterface remains instantiated, including across all re-\\ninitializations/reboots of the network management system,\\nincluding those which result in a change of the interface\'s\\nifIndex value.\\n\\nAn example of the value which a network manager might store\\nin this object for a WAN interface is the (Telco\'s) circuit\\nnumber/identifier of the interface.\\n\\nSome agents may support write-access only for interfaces\\nhaving particular values of ifType.  An agent which supports\\nwrite access to this object is required to keep the value in\\nnon-volatile storage, but it may limit the length of new\\nvalues depending on how much storage is already occupied by\\nthe current values for other interfaces.\",\"index\":[],\"name\":\"ifAlias\",\"objectID\":\"1.3.6.1.2.1.31.1.1.1.18\",\"pid\":\"1.3.6.1.2.1.31.1.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The value of sysUpTime on the most recent occasion at which\\nany one or more of this interface\'s counters suffered a\\ndiscontinuity.  The relevant counters are the specific\\ninstances associated with this interface of any Counter32 or\\n\\nCounter64 object contained in the ifTable or ifXTable.  If\\nno such discontinuities have occurred since the last re-\\ninitialization of the local management subsystem, then this\\nobject contains a zero value.\",\"index\":[],\"name\":\"ifCounterDiscontinuityTime\",\"objectID\":\"1.3.6.1.2.1.31.1.1.1.19\",\"pid\":\"1.3.6.1.2.1.31.1.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"},{\"access\":\"not-accessible\",\"description\":\"The table containing information on the relationships\\nbetween the multiple sub-layers of network interfaces.  In\\nparticular, it contains information on which sub-layers run\\n\'on top of\' which other sub-layers, where each sub-layer\\ncorresponds to a conceptual row in the ifTable.  For\\nexample, when the sub-layer with ifIndex value x runs over\\nthe sub-layer with ifIndex value y, then this table\\ncontains:\\n\\n  ifStackStatus.x.y=active\\n\\nFor each ifIndex value, I, which identifies an active\\ninterface, there are always at least two instantiated rows\\nin this table associated with I.  For one of these rows, I\\nis the value of ifStackHigherLayer; for the other, I is the\\nvalue of ifStackLowerLayer.  (If I is not involved in\\nmultiplexing, then these are the only two rows associated\\nwith I.)\\n\\nFor example, two rows exist even for an interface which has\\nno others stacked on top or below it:\\n\\n  ifStackStatus.0.x=active\\n  ifStackStatus.x.0=active \",\"index\":[],\"name\":\"ifStackTable\",\"objectID\":\"1.3.6.1.2.1.31.1.2\",\"pid\":\"1.3.6.1.2.1.31.1\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"Information on a particular relationship between two sub-\\nlayers, specifying that one sub-layer runs on \'top\' of the\\nother sub-layer.  Each sub-layer corresponds to a conceptual\\nrow in the ifTable.\",\"index\":[\"1.3.6.1.2.1.31.1.2.1.1\",\"1.3.6.1.2.1.31.1.2.1.2\"],\"name\":\"ifStackEntry\",\"objectID\":\"1.3.6.1.2.1.31.1.2.1\",\"pid\":\"1.3.6.1.2.1.31.1.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"The value of ifIndex corresponding to the higher sub-layer\\nof the relationship, i.e., the sub-layer which runs on \'top\'\\nof the sub-layer identified by the corresponding instance of\\nifStackLowerLayer.  If there is no higher sub-layer (below\\nthe internetwork layer), then this object has the value 0.\",\"index\":[],\"name\":\"ifStackHigherLayer\",\"objectID\":\"1.3.6.1.2.1.31.1.2.1.1\",\"pid\":\"1.3.6.1.2.1.31.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"The value of ifIndex corresponding to the lower sub-layer\\nof the relationship, i.e., the sub-layer which runs \'below\'\\nthe sub-layer identified by the corresponding instance of\\nifStackHigherLayer.  If there is no lower sub-layer, then\\nthis object has the value 0.\",\"index\":[],\"name\":\"ifStackLowerLayer\",\"objectID\":\"1.3.6.1.2.1.31.1.2.1.2\",\"pid\":\"1.3.6.1.2.1.31.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The status of the relationship between two sub-layers.\\n\\nChanging the value of this object from \'active\' to\\n\'notInService\' or \'destroy\' will likely have consequences up\\nand down the interface stack.  Thus, write access to this\\nobject is likely to be inappropriate for some types of\\ninterfaces, and many implementations will choose not to\\nsupport write-access for any type of interface.\",\"index\":[],\"name\":\"ifStackStatus\",\"objectID\":\"1.3.6.1.2.1.31.1.2.1.3\",\"pid\":\"1.3.6.1.2.1.31.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"},{\"access\":\"read-only\",\"description\":\"The value of sysUpTime at the time of the last change of\\nthe (whole) interface stack.  A change of the interface\\nstack is defined to be any creation, deletion, or change in\\nvalue of any instance of ifStackStatus.  If the interface\\nstack has been unchanged since the last re-initialization of\\nthe local network management subsystem, then this object\\ncontains a zero value.\",\"index\":[],\"name\":\"ifStackLastChange\",\"objectID\":\"1.3.6.1.2.1.31.1.6\",\"pid\":\"1.3.6.1.2.1.31.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"This table contains an entry for each address (broadcast,\\nmulticast, or uni-cast) for which the system will receive\\npackets/frames on a particular interface, except as follows:\\n\\n- for an interface operating in promiscuous mode, entries\\nare only required for those addresses for which the system\\nwould receive frames were it not operating in promiscuous\\nmode.\\n\\n- for 802.5 functional addresses, only one entry is\\nrequired, for the address which has the functional address\\nbit ANDed with the bit mask of all functional addresses for\\nwhich the interface will accept frames.\\n\\nA system is normally able to use any unicast address which\\ncorresponds to an entry in this table as a source address.\",\"index\":[],\"name\":\"ifRcvAddressTable\",\"objectID\":\"1.3.6.1.2.1.31.1.4\",\"pid\":\"1.3.6.1.2.1.31.1\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"A list of objects identifying an address for which the\\nsystem will accept packets/frames on the particular\\ninterface identified by the index value ifIndex.\",\"index\":[\"1.3.6.1.2.1.2.2.1.1\",\"1.3.6.1.2.1.31.1.4.1.1\"],\"name\":\"ifRcvAddressEntry\",\"objectID\":\"1.3.6.1.2.1.31.1.4.1\",\"pid\":\"1.3.6.1.2.1.31.1.4\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"An address for which the system will accept packets/frames\\non this entry\'s interface.\",\"index\":[],\"name\":\"ifRcvAddressAddress\",\"objectID\":\"1.3.6.1.2.1.31.1.4.1.1\",\"pid\":\"1.3.6.1.2.1.31.1.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object is used to create and delete rows in the\\nifRcvAddressTable.\",\"index\":[],\"name\":\"ifRcvAddressStatus\",\"objectID\":\"1.3.6.1.2.1.31.1.4.1.2\",\"pid\":\"1.3.6.1.2.1.31.1.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object has the value nonVolatile(3) for those entries\\nin the table which are valid and will not be deleted by the\\nnext restart of the managed system.  Entries having the\\nvalue volatile(2) are valid and exist, but have not been\\nsaved, so that will not exist after the next restart of the\\nmanaged system.  Entries having the value other(1) are valid\\nand exist but are not classified as to whether they will\\ncontinue to exist after the next restart.\",\"index\":[],\"name\":\"ifRcvAddressType\",\"objectID\":\"1.3.6.1.2.1.31.1.4.1.3\",\"pid\":\"1.3.6.1.2.1.31.1.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"},{\"access\":\"not-accessible\",\"description\":\"This table contains one entry per interface.  It defines\\nobjects which allow a network manager to instruct an agent\\nto test an interface for various faults.  Tests for an\\ninterface are defined in the media-specific MIB for that\\ninterface.  After invoking a test, the object ifTestResult\\ncan be read to determine the outcome.  If an agent can not\\nperform the test, ifTestResult is set to so indicate.  The\\nobject ifTestCode can be used to provide further test-\\nspecific or interface-specific (or even enterprise-specific)\\ninformation concerning the outcome of the test.  Only one\\ntest can be in progress on each interface at any one time.\\nIf one test is in progress when another test is invoked, the\\nsecond test is rejected.  Some agents may reject a test when\\na prior test is active on another interface.\\n\\nBefore starting a test, a manager-station must first obtain\\n\'ownership\' of the entry in the ifTestTable for the\\ninterface to be tested.  This is accomplished with the\\nifTestId and ifTestStatus objects as follows:\\n\\ntry_again:\\n  get (ifTestId, ifTestStatus)\\n  while (ifTestStatus != notInUse)\\n      /*\\n       * Loop while a test is running or some other\\n       * manager is configuring a test.\\n       */\\n      short delay\\n      get (ifTestId, ifTestStatus)\\n  }\\n\\n  /*\\n   * Is not being used right now -- let\'s compete\\n   * to see who gets it.\\n   */\\n  lock_value = ifTestId\\n\\n  if ( set(ifTestId = lock_value, ifTestStatus = inUse,\\n           ifTestOwner = \'my-IP-address\') == FAILURE)\\n      /*\\n       * Another manager got the ifTestEntry -- go\\n       * try again\\n       */\\n      goto try_again;\\n\\n  /*\\n   * I have the lock\\n   */\\n  set up any test parameters.\\n\\n  /*\\n   * This starts the test\\n   */\\n  set(ifTestType = test_to_run);\\n\\n  wait for test completion by polling ifTestResult\\n\\n  when test completes, agent sets ifTestResult\\n       agent also sets ifTestStatus = \'notInUse\'\\n\\n  retrieve any additional test results, and ifTestId\\n\\n  if (ifTestId == lock_value+1) results are valid\\n\\nA manager station first retrieves the value of the\\nappropriate ifTestId and ifTestStatus objects, periodically\\nrepeating the retrieval if necessary, until the value of\\nifTestStatus is \'notInUse\'.  The manager station then tries\\nto set the same ifTestId object to the value it just\\nretrieved, the same ifTestStatus object to \'inUse\', and the\\ncorresponding ifTestOwner object to a value indicating\\nitself.  If the set operation succeeds then the manager has\\nobtained ownership of the ifTestEntry, and the value of the\\nifTestId object is incremented by the agent (per the\\nsemantics of TestAndIncr).  Failure of the set operation\\nindicates that some other manager has obtained ownership of\\nthe ifTestEntry.\\n\\nOnce ownership is obtained, any test parameters can be\\nsetup, and then the test is initiated by setting ifTestType.\\nOn completion of the test, the agent sets ifTestStatus to\\n\'notInUse\'.  Once this occurs, the manager can retrieve the\\nresults.  In the (rare) event that the invocation of tests\\nby two network managers were to overlap, then there would be\\na possibility that the first test\'s results might be\\noverwritten by the second test\'s results prior to the first\\n\\nresults being read.  This unlikely circumstance can be\\ndetected by a network manager retrieving ifTestId at the\\nsame time as retrieving the test results, and ensuring that\\nthe results are for the desired request.\\n\\nIf ifTestType is not set within an abnormally long period of\\ntime after ownership is obtained, the agent should time-out\\nthe manager, and reset the value of the ifTestStatus object\\nback to \'notInUse\'.  It is suggested that this time-out\\nperiod be 5 minutes.\\n\\nIn general, a management station must not retransmit a\\nrequest to invoke a test for which it does not receive a\\nresponse; instead, it properly inspects an agent\'s MIB to\\ndetermine if the invocation was successful.  Only if the\\ninvocation was unsuccessful, is the invocation request\\nretransmitted.\\n\\nSome tests may require the interface to be taken off-line in\\norder to execute them, or may even require the agent to\\nreboot after completion of the test.  In these\\ncircumstances, communication with the management station\\ninvoking the test may be lost until after completion of the\\ntest.  An agent is not required to support such tests.\\nHowever, if such tests are supported, then the agent should\\nmake every effort to transmit a response to the request\\nwhich invoked the test prior to losing communication.  When\\nthe agent is restored to normal service, the results of the\\ntest are properly made available in the appropriate objects.\\nNote that this requires that the ifIndex value assigned to\\nan interface must be unchanged even if the test causes a\\nreboot.  An agent must reject any test for which it cannot,\\nperhaps due to resource constraints, make available at least\\nthe minimum amount of information after that test\\ncompletes.\",\"index\":[],\"name\":\"ifTestTable\",\"objectID\":\"1.3.6.1.2.1.31.1.3\",\"pid\":\"1.3.6.1.2.1.31.1\",\"status\":\"deprecated\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"An entry containing objects for invoking tests on an\\ninterface.\",\"index\":[],\"name\":\"ifTestEntry\",\"objectID\":\"1.3.6.1.2.1.31.1.3.1\",\"pid\":\"1.3.6.1.2.1.31.1.3\",\"status\":\"deprecated\",\"subTree\":[{\"access\":\"read-write\",\"description\":\"This object identifies the current invocation of the\\ninterface\'s test.\",\"index\":[],\"name\":\"ifTestId\",\"objectID\":\"1.3.6.1.2.1.31.1.3.1.1\",\"pid\":\"1.3.6.1.2.1.31.1.3.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"This object indicates whether or not some manager currently\\nhas the necessary \'ownership\' required to invoke a test on\\nthis interface.  A write to this object is only successful\\nwhen it changes its value from \'notInUse(1)\' to \'inUse(2)\'.\\nAfter completion of a test, the agent resets the value back\\nto \'notInUse(1)\'.\",\"index\":[],\"name\":\"ifTestStatus\",\"objectID\":\"1.3.6.1.2.1.31.1.3.1.2\",\"pid\":\"1.3.6.1.2.1.31.1.3.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"A control variable used to start and stop operator-\\ninitiated interface tests.  Most OBJECT IDENTIFIER values\\nassigned to tests are defined elsewhere, in association with\\nspecific types of interface.  However, this document assigns\\na value for a full-duplex loopback test, and defines the\\nspecial meanings of the subject identifier:\\n\\n    noTest  OBJECT IDENTIFIER ::= { 0 0 }\\n\\nWhen the value noTest is written to this object, no action\\nis taken unless a test is in progress, in which case the\\ntest is aborted.  Writing any other value to this object is\\n\\nonly valid when no test is currently in progress, in which\\ncase the indicated test is initiated.\\n\\nWhen read, this object always returns the most recent value\\nthat ifTestType was set to.  If it has not been set since\\nthe last initialization of the network management subsystem\\non the agent, a value of noTest is returned.\",\"index\":[],\"name\":\"ifTestType\",\"objectID\":\"1.3.6.1.2.1.31.1.3.1.3\",\"pid\":\"1.3.6.1.2.1.31.1.3.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"OBJECT IDENTIFIER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"This object contains the result of the most recently\\nrequested test, or the value none(1) if no tests have been\\nrequested since the last reset.  Note that this facility\\nprovides no provision for saving the results of one test\\nwhen starting another, as could be required if used by\\nmultiple managers concurrently.\",\"index\":[],\"name\":\"ifTestResult\",\"objectID\":\"1.3.6.1.2.1.31.1.3.1.4\",\"pid\":\"1.3.6.1.2.1.31.1.3.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"This object contains a code which contains more specific\\ninformation on the test result, for example an error-code\\nafter a failed test.  Error codes and other values this\\nobject may take are specific to the type of interface and/or\\ntest.  The value may have the semantics of either the\\nAutonomousType or InstancePointer textual conventions as\\ndefined in RFC 2579.  The identifier:\\n\\n    testCodeUnknown  OBJECT IDENTIFIER ::= { 0 0 }\\n\\nis defined for use if no additional result code is\\navailable.\",\"index\":[],\"name\":\"ifTestCode\",\"objectID\":\"1.3.6.1.2.1.31.1.3.1.5\",\"pid\":\"1.3.6.1.2.1.31.1.3.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"OBJECT IDENTIFIER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The entity which currently has the \'ownership\' required to\\ninvoke a test on this interface.\",\"index\":[],\"name\":\"ifTestOwner\",\"objectID\":\"1.3.6.1.2.1.31.1.3.1.6\",\"pid\":\"1.3.6.1.2.1.31.1.3.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"}],\"type\":\"IDENTIFIER\"},{\"access\":\"read-create\",\"description\":\"This object has the value nonVolatile(3) for those entries\\nin the table which are valid and will not be deleted by the\\nnext restart of the managed system.  Entries having the\\nvalue volatile(2) are valid and exist, but have not been\\nsaved, so that will not exist after the next restart of the\\nmanaged system.  Entries having the value other(1) are valid\\nand exist but are not classified as to whether they will\\ncontinue to exist after the next restart.\",\"index\":[],\"name\":\"ifConformance\",\"objectID\":\"1.3.6.1.2.1.31.2\",\"pid\":\"1.3.6.1.2.1.31\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-create\",\"description\":\"This object has the value nonVolatile(3) for those entries\\nin the table which are valid and will not be deleted by the\\nnext restart of the managed system.  Entries having the\\nvalue volatile(2) are valid and exist, but have not been\\nsaved, so that will not exist after the next restart of the\\nmanaged system.  Entries having the value other(1) are valid\\nand exist but are not classified as to whether they will\\ncontinue to exist after the next restart.\",\"index\":[],\"name\":\"ifGroups\",\"objectID\":\"1.3.6.1.2.1.31.2.1\",\"pid\":\"1.3.6.1.2.1.31.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-create\",\"description\":\"This object has the value nonVolatile(3) for those entries\\nin the table which are valid and will not be deleted by the\\nnext restart of the managed system.  Entries having the\\nvalue volatile(2) are valid and exist, but have not been\\nsaved, so that will not exist after the next restart of the\\nmanaged system.  Entries having the value other(1) are valid\\nand exist but are not classified as to whether they will\\ncontinue to exist after the next restart.\",\"index\":[],\"name\":\"ifGeneralInformationGroup\",\"objectID\":\"1.3.6.1.2.1.31.2.1.10\",\"pid\":\"1.3.6.1.2.1.31.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object has the value nonVolatile(3) for those entries\\nin the table which are valid and will not be deleted by the\\nnext restart of the managed system.  Entries having the\\nvalue volatile(2) are valid and exist, but have not been\\nsaved, so that will not exist after the next restart of the\\nmanaged system.  Entries having the value other(1) are valid\\nand exist but are not classified as to whether they will\\ncontinue to exist after the next restart.\",\"index\":[],\"name\":\"ifFixedLengthGroup\",\"objectID\":\"1.3.6.1.2.1.31.2.1.2\",\"pid\":\"1.3.6.1.2.1.31.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object has the value nonVolatile(3) for those entries\\nin the table which are valid and will not be deleted by the\\nnext restart of the managed system.  Entries having the\\nvalue volatile(2) are valid and exist, but have not been\\nsaved, so that will not exist after the next restart of the\\nmanaged system.  Entries having the value other(1) are valid\\nand exist but are not classified as to whether they will\\ncontinue to exist after the next restart.\",\"index\":[],\"name\":\"ifHCFixedLengthGroup\",\"objectID\":\"1.3.6.1.2.1.31.2.1.3\",\"pid\":\"1.3.6.1.2.1.31.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object has the value nonVolatile(3) for those entries\\nin the table which are valid and will not be deleted by the\\nnext restart of the managed system.  Entries having the\\nvalue volatile(2) are valid and exist, but have not been\\nsaved, so that will not exist after the next restart of the\\nmanaged system.  Entries having the value other(1) are valid\\nand exist but are not classified as to whether they will\\ncontinue to exist after the next restart.\",\"index\":[],\"name\":\"ifPacketGroup\",\"objectID\":\"1.3.6.1.2.1.31.2.1.4\",\"pid\":\"1.3.6.1.2.1.31.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object has the value nonVolatile(3) for those entries\\nin the table which are valid and will not be deleted by the\\nnext restart of the managed system.  Entries having the\\nvalue volatile(2) are valid and exist, but have not been\\nsaved, so that will not exist after the next restart of the\\nmanaged system.  Entries having the value other(1) are valid\\nand exist but are not classified as to whether they will\\ncontinue to exist after the next restart.\",\"index\":[],\"name\":\"ifHCPacketGroup\",\"objectID\":\"1.3.6.1.2.1.31.2.1.5\",\"pid\":\"1.3.6.1.2.1.31.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object has the value nonVolatile(3) for those entries\\nin the table which are valid and will not be deleted by the\\nnext restart of the managed system.  Entries having the\\nvalue volatile(2) are valid and exist, but have not been\\nsaved, so that will not exist after the next restart of the\\nmanaged system.  Entries having the value other(1) are valid\\nand exist but are not classified as to whether they will\\ncontinue to exist after the next restart.\",\"index\":[],\"name\":\"ifVHCPacketGroup\",\"objectID\":\"1.3.6.1.2.1.31.2.1.6\",\"pid\":\"1.3.6.1.2.1.31.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object has the value nonVolatile(3) for those entries\\nin the table which are valid and will not be deleted by the\\nnext restart of the managed system.  Entries having the\\nvalue volatile(2) are valid and exist, but have not been\\nsaved, so that will not exist after the next restart of the\\nmanaged system.  Entries having the value other(1) are valid\\nand exist but are not classified as to whether they will\\ncontinue to exist after the next restart.\",\"index\":[],\"name\":\"ifRcvAddressGroup\",\"objectID\":\"1.3.6.1.2.1.31.2.1.7\",\"pid\":\"1.3.6.1.2.1.31.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object has the value nonVolatile(3) for those entries\\nin the table which are valid and will not be deleted by the\\nnext restart of the managed system.  Entries having the\\nvalue volatile(2) are valid and exist, but have not been\\nsaved, so that will not exist after the next restart of the\\nmanaged system.  Entries having the value other(1) are valid\\nand exist but are not classified as to whether they will\\ncontinue to exist after the next restart.\",\"index\":[],\"name\":\"ifStackGroup2\",\"objectID\":\"1.3.6.1.2.1.31.2.1.11\",\"pid\":\"1.3.6.1.2.1.31.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object has the value nonVolatile(3) for those entries\\nin the table which are valid and will not be deleted by the\\nnext restart of the managed system.  Entries having the\\nvalue volatile(2) are valid and exist, but have not been\\nsaved, so that will not exist after the next restart of the\\nmanaged system.  Entries having the value other(1) are valid\\nand exist but are not classified as to whether they will\\ncontinue to exist after the next restart.\",\"index\":[],\"name\":\"ifCounterDiscontinuityGroup\",\"objectID\":\"1.3.6.1.2.1.31.2.1.13\",\"pid\":\"1.3.6.1.2.1.31.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object has the value nonVolatile(3) for those entries\\nin the table which are valid and will not be deleted by the\\nnext restart of the managed system.  Entries having the\\nvalue volatile(2) are valid and exist, but have not been\\nsaved, so that will not exist after the next restart of the\\nmanaged system.  Entries having the value other(1) are valid\\nand exist but are not classified as to whether they will\\ncontinue to exist after the next restart.\",\"index\":[],\"name\":\"linkUpDownNotificationsGroup\",\"objectID\":\"1.3.6.1.2.1.31.2.1.14\",\"pid\":\"1.3.6.1.2.1.31.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The entity which currently has the \'ownership\' required to\\ninvoke a test on this interface.\",\"index\":[],\"name\":\"ifGeneralGroup\",\"objectID\":\"1.3.6.1.2.1.31.2.1.1\",\"pid\":\"1.3.6.1.2.1.31.2.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The entity which currently has the \'ownership\' required to\\ninvoke a test on this interface.\",\"index\":[],\"name\":\"ifTestGroup\",\"objectID\":\"1.3.6.1.2.1.31.2.1.8\",\"pid\":\"1.3.6.1.2.1.31.2.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The entity which currently has the \'ownership\' required to\\ninvoke a test on this interface.\",\"index\":[],\"name\":\"ifStackGroup\",\"objectID\":\"1.3.6.1.2.1.31.2.1.9\",\"pid\":\"1.3.6.1.2.1.31.2.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The entity which currently has the \'ownership\' required to\\ninvoke a test on this interface.\",\"index\":[],\"name\":\"ifOldObjectsGroup\",\"objectID\":\"1.3.6.1.2.1.31.2.1.12\",\"pid\":\"1.3.6.1.2.1.31.2.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"},{\"access\":\"read-create\",\"description\":\"This object has the value nonVolatile(3) for those entries\\nin the table which are valid and will not be deleted by the\\nnext restart of the managed system.  Entries having the\\nvalue volatile(2) are valid and exist, but have not been\\nsaved, so that will not exist after the next restart of the\\nmanaged system.  Entries having the value other(1) are valid\\nand exist but are not classified as to whether they will\\ncontinue to exist after the next restart.\",\"index\":[],\"name\":\"ifCompliances\",\"objectID\":\"1.3.6.1.2.1.31.2.2\",\"pid\":\"1.3.6.1.2.1.31.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-create\",\"description\":\"This object has the value nonVolatile(3) for those entries\\nin the table which are valid and will not be deleted by the\\nnext restart of the managed system.  Entries having the\\nvalue volatile(2) are valid and exist, but have not been\\nsaved, so that will not exist after the next restart of the\\nmanaged system.  Entries having the value other(1) are valid\\nand exist but are not classified as to whether they will\\ncontinue to exist after the next restart.\",\"index\":[],\"name\":\"ifCompliance3\",\"objectID\":\"1.3.6.1.2.1.31.2.2.3\",\"pid\":\"1.3.6.1.2.1.31.2.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The entity which currently has the \'ownership\' required to\\ninvoke a test on this interface.\",\"index\":[],\"name\":\"ifCompliance\",\"objectID\":\"1.3.6.1.2.1.31.2.2.1\",\"pid\":\"1.3.6.1.2.1.31.2.2\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The entity which currently has the \'ownership\' required to\\ninvoke a test on this interface.\",\"index\":[],\"name\":\"ifCompliance2\",\"objectID\":\"1.3.6.1.2.1.31.2.2.2\",\"pid\":\"1.3.6.1.2.1.31.2.2\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"}],\"type\":\"OBJECT\"},{\"index\":[],\"name\":\"interfaces\",\"objectID\":\"1.3.6.1.2.1.2\",\"pid\":\"1.3.6.1.2.1\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The number of network interfaces (regardless of their\\ncurrent state) present on this system.\",\"index\":[],\"name\":\"ifNumber\",\"objectID\":\"1.3.6.1.2.1.2.1\",\"pid\":\"1.3.6.1.2.1.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"A list of interface entries.  The number of entries is\\ngiven by the value of ifNumber.\",\"index\":[],\"name\":\"ifTable\",\"objectID\":\"1.3.6.1.2.1.2.2\",\"pid\":\"1.3.6.1.2.1.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"An entry containing management information applicable to a\\nparticular interface.\",\"index\":[\"1.3.6.1.2.1.2.2.1.1\"],\"name\":\"ifEntry\",\"objectID\":\"1.3.6.1.2.1.2.2.1\",\"pid\":\"1.3.6.1.2.1.2.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"A unique value, greater than zero, for each interface.  It\\nis recommended that values are assigned contiguously\\nstarting from 1.  The value for each interface sub-layer\\nmust remain constant at least from one re-initialization of\\nthe entity\'s network management system to the next re-\\ninitialization.\",\"index\":[],\"name\":\"ifIndex\",\"objectID\":\"1.3.6.1.2.1.2.2.1.1\",\"pid\":\"1.3.6.1.2.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"A textual string containing information about the\\ninterface.  This string should include the name of the\\nmanufacturer, the product name and the version of the\\ninterface hardware/software.\",\"index\":[],\"name\":\"ifDescr\",\"objectID\":\"1.3.6.1.2.1.2.2.1.2\",\"pid\":\"1.3.6.1.2.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The type of interface.  Additional values for ifType are\\nassigned by the Internet Assigned Numbers Authority (IANA),\\nthrough updating the syntax of the IANAifType textual\\nconvention.\",\"index\":[],\"name\":\"ifType\",\"objectID\":\"1.3.6.1.2.1.2.2.1.3\",\"pid\":\"1.3.6.1.2.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The size of the largest packet which can be sent/received\\non the interface, specified in octets.  For interfaces that\\nare used for transmitting network datagrams, this is the\\nsize of the largest network datagram that can be sent on the\\ninterface.\",\"index\":[],\"name\":\"ifMtu\",\"objectID\":\"1.3.6.1.2.1.2.2.1.4\",\"pid\":\"1.3.6.1.2.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"An estimate of the interface\'s current bandwidth in bits\\nper second.  For interfaces which do not vary in bandwidth\\nor for those where no accurate estimation can be made, this\\nobject should contain the nominal bandwidth.  If the\\nbandwidth of the interface is greater than the maximum value\\nreportable by this object then this object should report its\\nmaximum value (4,294,967,295) and ifHighSpeed must be used\\nto report the interace\'s speed.  For a sub-layer which has\\nno concept of bandwidth, this object should be zero.\",\"index\":[],\"name\":\"ifSpeed\",\"objectID\":\"1.3.6.1.2.1.2.2.1.5\",\"pid\":\"1.3.6.1.2.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The interface\'s address at its protocol sub-layer.  For\\nexample, for an 802.x interface, this object normally\\ncontains a MAC address.  The interface\'s media-specific MIB\\nmust define the bit and byte ordering and the format of the\\nvalue of this object.  For interfaces which do not have such\\nan address (e.g., a serial line), this object should contain\\nan octet string of zero length.\",\"index\":[],\"name\":\"ifPhysAddress\",\"objectID\":\"1.3.6.1.2.1.2.2.1.6\",\"pid\":\"1.3.6.1.2.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The desired state of the interface.  The testing(3) state\\nindicates that no operational packets can be passed.  When a\\nmanaged system initializes, all interfaces start with\\nifAdminStatus in the down(2) state.  As a result of either\\nexplicit management action or per configuration information\\nretained by the managed system, ifAdminStatus is then\\nchanged to either the up(1) or testing(3) states (or remains\\nin the down(2) state).\",\"index\":[],\"name\":\"ifAdminStatus\",\"objectID\":\"1.3.6.1.2.1.2.2.1.7\",\"pid\":\"1.3.6.1.2.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The current operational state of the interface.  The\\ntesting(3) state indicates that no operational packets can\\nbe passed.  If ifAdminStatus is down(2) then ifOperStatus\\nshould be down(2).  If ifAdminStatus is changed to up(1)\\nthen ifOperStatus should change to up(1) if the interface is\\nready to transmit and receive network traffic; it should\\nchange to dormant(5) if the interface is waiting for\\nexternal actions (such as a serial line waiting for an\\nincoming connection); it should remain in the down(2) state\\nif and only if there is a fault that prevents it from going\\nto the up(1) state; it should remain in the notPresent(6)\\nstate if the interface has missing (typically, hardware)\\ncomponents.\",\"index\":[],\"name\":\"ifOperStatus\",\"objectID\":\"1.3.6.1.2.1.2.2.1.8\",\"pid\":\"1.3.6.1.2.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The value of sysUpTime at the time the interface entered\\nits current operational state.  If the current state was\\nentered prior to the last re-initialization of the local\\nnetwork management subsystem, then this object contains a\\nzero value.\",\"index\":[],\"name\":\"ifLastChange\",\"objectID\":\"1.3.6.1.2.1.2.2.1.9\",\"pid\":\"1.3.6.1.2.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of octets received on the interface,\\nincluding framing characters.\\n\\nDiscontinuities in the value of this counter can occur at\\nre-initialization of the management system, and at other\\ntimes as indicated by the value of\\nifCounterDiscontinuityTime.\",\"index\":[],\"name\":\"ifInOctets\",\"objectID\":\"1.3.6.1.2.1.2.2.1.10\",\"pid\":\"1.3.6.1.2.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of packets, delivered by this sub-layer to a\\nhigher (sub-)layer, which were not addressed to a multicast\\nor broadcast address at this sub-layer.\\n\\nDiscontinuities in the value of this counter can occur at\\nre-initialization of the management system, and at other\\ntimes as indicated by the value of\\nifCounterDiscontinuityTime.\",\"index\":[],\"name\":\"ifInUcastPkts\",\"objectID\":\"1.3.6.1.2.1.2.2.1.11\",\"pid\":\"1.3.6.1.2.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of packets, delivered by this sub-layer to a\\nhigher (sub-)layer, which were addressed to a multicast or\\nbroadcast address at this sub-layer.\\n\\nDiscontinuities in the value of this counter can occur at\\nre-initialization of the management system, and at other\\ntimes as indicated by the value of\\nifCounterDiscontinuityTime.\\n\\nThis object is deprecated in favour of ifInMulticastPkts and\\nifInBroadcastPkts.\",\"index\":[],\"name\":\"ifInNUcastPkts\",\"objectID\":\"1.3.6.1.2.1.2.2.1.12\",\"pid\":\"1.3.6.1.2.1.2.2.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of inbound packets which were chosen to be\\ndiscarded even though no errors had been detected to prevent\\n\\ntheir being deliverable to a higher-layer protocol.  One\\npossible reason for discarding such a packet could be to\\nfree up buffer space.\\n\\nDiscontinuities in the value of this counter can occur at\\nre-initialization of the management system, and at other\\ntimes as indicated by the value of\\nifCounterDiscontinuityTime.\",\"index\":[],\"name\":\"ifInDiscards\",\"objectID\":\"1.3.6.1.2.1.2.2.1.13\",\"pid\":\"1.3.6.1.2.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"For packet-oriented interfaces, the number of inbound\\npackets that contained errors preventing them from being\\ndeliverable to a higher-layer protocol.  For character-\\noriented or fixed-length interfaces, the number of inbound\\ntransmission units that contained errors preventing them\\nfrom being deliverable to a higher-layer protocol.\\n\\nDiscontinuities in the value of this counter can occur at\\nre-initialization of the management system, and at other\\ntimes as indicated by the value of\\nifCounterDiscontinuityTime.\",\"index\":[],\"name\":\"ifInErrors\",\"objectID\":\"1.3.6.1.2.1.2.2.1.14\",\"pid\":\"1.3.6.1.2.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"For packet-oriented interfaces, the number of packets\\nreceived via the interface which were discarded because of\\nan unknown or unsupported protocol.  For character-oriented\\nor fixed-length interfaces that support protocol\\nmultiplexing the number of transmission units received via\\nthe interface which were discarded because of an unknown or\\nunsupported protocol.  For any interface that does not\\nsupport protocol multiplexing, this counter will always be\\n0.\\n\\nDiscontinuities in the value of this counter can occur at\\nre-initialization of the management system, and at other\\ntimes as indicated by the value of\\nifCounterDiscontinuityTime.\",\"index\":[],\"name\":\"ifInUnknownProtos\",\"objectID\":\"1.3.6.1.2.1.2.2.1.15\",\"pid\":\"1.3.6.1.2.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of octets transmitted out of the\\ninterface, including framing characters.\\n\\nDiscontinuities in the value of this counter can occur at\\nre-initialization of the management system, and at other\\ntimes as indicated by the value of\\nifCounterDiscontinuityTime.\",\"index\":[],\"name\":\"ifOutOctets\",\"objectID\":\"1.3.6.1.2.1.2.2.1.16\",\"pid\":\"1.3.6.1.2.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of packets that higher-level protocols\\nrequested be transmitted, and which were not addressed to a\\nmulticast or broadcast address at this sub-layer, including\\nthose that were discarded or not sent.\\n\\nDiscontinuities in the value of this counter can occur at\\nre-initialization of the management system, and at other\\ntimes as indicated by the value of\\nifCounterDiscontinuityTime.\",\"index\":[],\"name\":\"ifOutUcastPkts\",\"objectID\":\"1.3.6.1.2.1.2.2.1.17\",\"pid\":\"1.3.6.1.2.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of packets that higher-level protocols\\nrequested be transmitted, and which were addressed to a\\nmulticast or broadcast address at this sub-layer, including\\nthose that were discarded or not sent.\\n\\nDiscontinuities in the value of this counter can occur at\\nre-initialization of the management system, and at other\\ntimes as indicated by the value of\\nifCounterDiscontinuityTime.\\n\\nThis object is deprecated in favour of ifOutMulticastPkts\\nand ifOutBroadcastPkts.\",\"index\":[],\"name\":\"ifOutNUcastPkts\",\"objectID\":\"1.3.6.1.2.1.2.2.1.18\",\"pid\":\"1.3.6.1.2.1.2.2.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of outbound packets which were chosen to be\\ndiscarded even though no errors had been detected to prevent\\ntheir being transmitted.  One possible reason for discarding\\nsuch a packet could be to free up buffer space.\\n\\nDiscontinuities in the value of this counter can occur at\\nre-initialization of the management system, and at other\\ntimes as indicated by the value of\\nifCounterDiscontinuityTime.\",\"index\":[],\"name\":\"ifOutDiscards\",\"objectID\":\"1.3.6.1.2.1.2.2.1.19\",\"pid\":\"1.3.6.1.2.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"For packet-oriented interfaces, the number of outbound\\npackets that could not be transmitted because of errors.\\nFor character-oriented or fixed-length interfaces, the\\nnumber of outbound transmission units that could not be\\ntransmitted because of errors.\\n\\nDiscontinuities in the value of this counter can occur at\\nre-initialization of the management system, and at other\\ntimes as indicated by the value of\\nifCounterDiscontinuityTime.\",\"index\":[],\"name\":\"ifOutErrors\",\"objectID\":\"1.3.6.1.2.1.2.2.1.20\",\"pid\":\"1.3.6.1.2.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The length of the output packet queue (in packets).\",\"index\":[],\"name\":\"ifOutQLen\",\"objectID\":\"1.3.6.1.2.1.2.2.1.21\",\"pid\":\"1.3.6.1.2.1.2.2.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"A reference to MIB definitions specific to the particular\\nmedia being used to realize the interface.  It is\\n\\nrecommended that this value point to an instance of a MIB\\nobject in the media-specific MIB, i.e., that this object\\nhave the semantics associated with the InstancePointer\\ntextual convention defined in RFC 2579.  In fact, it is\\nrecommended that the media-specific MIB specify what value\\nifSpecific should/can take for values of ifType.  If no MIB\\ndefinitions specific to the particular media are available,\\nthe value should be set to the OBJECT IDENTIFIER { 0 0 }.\",\"index\":[],\"name\":\"ifSpecific\",\"objectID\":\"1.3.6.1.2.1.2.2.1.22\",\"pid\":\"1.3.6.1.2.1.2.2.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"OBJECT IDENTIFIER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"}],\"type\":\"IDENTIFIER\"},{\"access\":\"read-create\",\"description\":\"This object has the value nonVolatile(3) for those entries\\nin the table which are valid and will not be deleted by the\\nnext restart of the managed system.  Entries having the\\nvalue volatile(2) are valid and exist, but have not been\\nsaved, so that will not exist after the next restart of the\\nmanaged system.  Entries having the value other(1) are valid\\nand exist but are not classified as to whether they will\\ncontinue to exist after the next restart.\",\"index\":[],\"name\":\"linkDown\",\"objectID\":\"1.3.6.1.6.3.1.1.5.3\",\"pid\":\"1.3.6.1.6.3.1.1.5\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object has the value nonVolatile(3) for those entries\\nin the table which are valid and will not be deleted by the\\nnext restart of the managed system.  Entries having the\\nvalue volatile(2) are valid and exist, but have not been\\nsaved, so that will not exist after the next restart of the\\nmanaged system.  Entries having the value other(1) are valid\\nand exist but are not classified as to whether they will\\ncontinue to exist after the next restart.\",\"index\":[],\"name\":\"linkUp\",\"objectID\":\"1.3.6.1.6.3.1.1.5.4\",\"pid\":\"1.3.6.1.6.3.1.1.5\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}]}');
INSERT INTO `snmp_mib` VALUES (17, 'INET-ADDRESS-MIB', 'INET-ADDRESS-MIB.txt', , '', '', 1, '2021-09-29 11:57:50', '{\"INET-ADDRESS-MIB\":[{\"index\":[],\"name\":\"inetAddressMIB\",\"objectID\":\"1.3.6.1.2.1.76\",\"pid\":\"1.3.6.1.2.1\",\"subTree\":[],\"type\":\"OBJECT\"}]}');
INSERT INTO `snmp_mib` VALUES (18, 'IP-FORWARD-MIB', 'IP-FORWARD-MIB.txt', , '', '', 1, '2021-09-29 11:58:04', '{\"IP-FORWARD-MIB\":[{\"index\":[],\"name\":\"ipForward\",\"objectID\":\"1.3.6.1.2.1.4.24\",\"pid\":\"1.3.6.1.2.1.4\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The number of current inetCidrRouteTable entries that\\nare not invalid.\",\"index\":[],\"name\":\"inetCidrRouteNumber\",\"objectID\":\"1.3.6.1.2.1.4.24.6\",\"pid\":\"1.3.6.1.2.1.4.24\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of valid route entries discarded from the\\ninetCidrRouteTable.  Discarded route entries do not\\nappear in the inetCidrRouteTable.  One possible reason\\nfor discarding an entry would be to free-up buffer space\\nfor other route table entries.\",\"index\":[],\"name\":\"inetCidrRouteDiscards\",\"objectID\":\"1.3.6.1.2.1.4.24.8\",\"pid\":\"1.3.6.1.2.1.4.24\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"This entity\'s IP Routing table.\",\"index\":[],\"name\":\"inetCidrRouteTable\",\"objectID\":\"1.3.6.1.2.1.4.24.7\",\"pid\":\"1.3.6.1.2.1.4.24\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"A particular route to a particular destination, under a\\nparticular policy (as reflected in the\\ninetCidrRoutePolicy object).\\n\\nDynamically created rows will survive an agent reboot.\\n\\nImplementers need to be aware that if the total number\\nof elements (octets or sub-identifiers) in\\ninetCidrRouteDest, inetCidrRoutePolicy, and\\ninetCidrRouteNextHop exceeds 111, then OIDs of column\\ninstances in this table will have more than 128 sub-\\nidentifiers and cannot be accessed using SNMPv1,\\nSNMPv2c, or SNMPv3.\",\"index\":[\"1.3.6.1.2.1.4.24.7.1.1\",\"1.3.6.1.2.1.4.24.7.1.2\",\"1.3.6.1.2.1.4.24.7.1.3\",\"1.3.6.1.2.1.4.24.7.1.4\",\"1.3.6.1.2.1.4.24.7.1.5\",\"1.3.6.1.2.1.4.24.7.1.6\"],\"name\":\"inetCidrRouteEntry\",\"objectID\":\"1.3.6.1.2.1.4.24.7.1\",\"pid\":\"1.3.6.1.2.1.4.24.7\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"The type of the inetCidrRouteDest address, as defined\\nin the InetAddress MIB.\\n\\nOnly those address types that may appear in an actual\\nrouting table are allowed as values of this object.\",\"index\":[],\"name\":\"inetCidrRouteDestType\",\"objectID\":\"1.3.6.1.2.1.4.24.7.1.1\",\"pid\":\"1.3.6.1.2.1.4.24.7.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"The destination IP address of this route.\\n\\nThe type of this address is determined by the value of\\nthe inetCidrRouteDestType object.\\n\\nThe values for the index objects inetCidrRouteDest and\\ninetCidrRoutePfxLen must be consistent.  When the value\\nof inetCidrRouteDest (excluding the zone index, if one\\nis present) is x, then the bitwise logical-AND\\nof x with the value of the mask formed from the\\ncorresponding index object inetCidrRoutePfxLen MUST be\\nequal to x.  If not, then the index pair is not\\nconsistent and an inconsistentName error must be\\nreturned on SET or CREATE requests.\",\"index\":[],\"name\":\"inetCidrRouteDest\",\"objectID\":\"1.3.6.1.2.1.4.24.7.1.2\",\"pid\":\"1.3.6.1.2.1.4.24.7.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"Indicates the number of leading one bits that form the\\nmask to be logical-ANDed with the destination address\\nbefore being compared to the value in the\\n\\ninetCidrRouteDest field.\\n\\nThe values for the index objects inetCidrRouteDest and\\ninetCidrRoutePfxLen must be consistent.  When the value\\nof inetCidrRouteDest (excluding the zone index, if one\\nis present) is x, then the bitwise logical-AND\\nof x with the value of the mask formed from the\\ncorresponding index object inetCidrRoutePfxLen MUST be\\nequal to x.  If not, then the index pair is not\\nconsistent and an inconsistentName error must be\\nreturned on SET or CREATE requests.\",\"index\":[],\"name\":\"inetCidrRoutePfxLen\",\"objectID\":\"1.3.6.1.2.1.4.24.7.1.3\",\"pid\":\"1.3.6.1.2.1.4.24.7.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"This object is an opaque object without any defined\\nsemantics.  Its purpose is to serve as an additional\\nindex that may delineate between multiple entries to\\nthe same destination.  The value { 0 0 } shall be used\\nas the default value for this object.\",\"index\":[],\"name\":\"inetCidrRoutePolicy\",\"objectID\":\"1.3.6.1.2.1.4.24.7.1.4\",\"pid\":\"1.3.6.1.2.1.4.24.7.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OBJECT IDENTIFIER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"The type of the inetCidrRouteNextHop address, as\\ndefined in the InetAddress MIB.\\n\\nValue should be set to unknown(0) for non-remote\\nroutes.\\n\\nOnly those address types that may appear in an actual\\nrouting table are allowed as values of this object.\",\"index\":[],\"name\":\"inetCidrRouteNextHopType\",\"objectID\":\"1.3.6.1.2.1.4.24.7.1.5\",\"pid\":\"1.3.6.1.2.1.4.24.7.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"On remote routes, the address of the next system en\\n\\nroute.  For non-remote routes, a zero length string.\\n\\nThe type of this address is determined by the value of\\nthe inetCidrRouteNextHopType object.\",\"index\":[],\"name\":\"inetCidrRouteNextHop\",\"objectID\":\"1.3.6.1.2.1.4.24.7.1.6\",\"pid\":\"1.3.6.1.2.1.4.24.7.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The ifIndex value that identifies the local interface\\nthrough which the next hop of this route should be\\nreached.  A value of 0 is valid and represents the\\nscenario where no interface is specified.\",\"index\":[],\"name\":\"inetCidrRouteIfIndex\",\"objectID\":\"1.3.6.1.2.1.4.24.7.1.7\",\"pid\":\"1.3.6.1.2.1.4.24.7.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The type of route.  Note that local(3) refers to a\\nroute for which the next hop is the final destination;\\nremote(4) refers to a route for which the next hop is\\nnot the final destination.\\n\\nRoutes that do not result in traffic forwarding or\\nrejection should not be displayed, even if the\\nimplementation keeps them stored internally.\\n\\nreject(2) refers to a route that, if matched, discards\\nthe message as unreachable and returns a notification\\n(e.g., ICMP error) to the message sender.  This is used\\nin some protocols as a means of correctly aggregating\\nroutes.\\n\\nblackhole(5) refers to a route that, if matched,\\ndiscards the message silently.\",\"index\":[],\"name\":\"inetCidrRouteType\",\"objectID\":\"1.3.6.1.2.1.4.24.7.1.8\",\"pid\":\"1.3.6.1.2.1.4.24.7.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The routing mechanism via which this route was learned.\\nInclusion of values for gateway routing protocols is\\nnot intended to imply that hosts should support those\\nprotocols.\",\"index\":[],\"name\":\"inetCidrRouteProto\",\"objectID\":\"1.3.6.1.2.1.4.24.7.1.9\",\"pid\":\"1.3.6.1.2.1.4.24.7.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of seconds since this route was last updated\\nor otherwise determined to be correct.  Note that no\\nsemantics of \'too old\' can be implied, except through\\nknowledge of the routing protocol by which the route\\nwas learned.\",\"index\":[],\"name\":\"inetCidrRouteAge\",\"objectID\":\"1.3.6.1.2.1.4.24.7.1.10\",\"pid\":\"1.3.6.1.2.1.4.24.7.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The Autonomous System Number of the Next Hop.  The\\nsemantics of this object are determined by the routing-\\nprotocol specified in the route\'s inetCidrRouteProto\\nvalue.  When this object is unknown or not relevant, its\\nvalue should be set to zero.\",\"index\":[],\"name\":\"inetCidrRouteNextHopAS\",\"objectID\":\"1.3.6.1.2.1.4.24.7.1.11\",\"pid\":\"1.3.6.1.2.1.4.24.7.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The primary routing metric for this route.  The\\nsemantics of this metric are determined by the routing-\\nprotocol specified in the route\'s inetCidrRouteProto\\nvalue.  If this metric is not used, its value should be\\nset to -1.\",\"index\":[],\"name\":\"inetCidrRouteMetric1\",\"objectID\":\"1.3.6.1.2.1.4.24.7.1.12\",\"pid\":\"1.3.6.1.2.1.4.24.7.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"An alternate routing metric for this route.  The\\nsemantics of this metric are determined by the routing-\\nprotocol specified in the route\'s inetCidrRouteProto\\nvalue.  If this metric is not used, its value should be\\nset to -1.\",\"index\":[],\"name\":\"inetCidrRouteMetric2\",\"objectID\":\"1.3.6.1.2.1.4.24.7.1.13\",\"pid\":\"1.3.6.1.2.1.4.24.7.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"An alternate routing metric for this route.  The\\nsemantics of this metric are determined by the routing-\\nprotocol specified in the route\'s inetCidrRouteProto\\nvalue.  If this metric is not used, its value should be\\nset to -1.\",\"index\":[],\"name\":\"inetCidrRouteMetric3\",\"objectID\":\"1.3.6.1.2.1.4.24.7.1.14\",\"pid\":\"1.3.6.1.2.1.4.24.7.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"An alternate routing metric for this route.  The\\nsemantics of this metric are determined by the routing-\\nprotocol specified in the route\'s inetCidrRouteProto\\nvalue.  If this metric is not used, its value should be\\nset to -1.\",\"index\":[],\"name\":\"inetCidrRouteMetric4\",\"objectID\":\"1.3.6.1.2.1.4.24.7.1.15\",\"pid\":\"1.3.6.1.2.1.4.24.7.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"An alternate routing metric for this route.  The\\nsemantics of this metric are determined by the routing-\\n\\nprotocol specified in the route\'s inetCidrRouteProto\\nvalue.  If this metric is not used, its value should be\\nset to -1.\",\"index\":[],\"name\":\"inetCidrRouteMetric5\",\"objectID\":\"1.3.6.1.2.1.4.24.7.1.16\",\"pid\":\"1.3.6.1.2.1.4.24.7.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The row status variable, used according to row\\ninstallation and removal conventions.\\n\\nA row entry cannot be modified when the status is\\nmarked as active(1).\",\"index\":[],\"name\":\"inetCidrRouteStatus\",\"objectID\":\"1.3.6.1.2.1.4.24.7.1.17\",\"pid\":\"1.3.6.1.2.1.4.24.7.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"},{\"access\":\"read-create\",\"description\":\"The row status variable, used according to row\\ninstallation and removal conventions.\\n\\nA row entry cannot be modified when the status is\\nmarked as active(1).\",\"index\":[],\"name\":\"ipForwardConformance\",\"objectID\":\"1.3.6.1.2.1.4.24.5\",\"pid\":\"1.3.6.1.2.1.4.24\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-create\",\"description\":\"The row status variable, used according to row\\ninstallation and removal conventions.\\n\\nA row entry cannot be modified when the status is\\nmarked as active(1).\",\"index\":[],\"name\":\"ipForwardGroups\",\"objectID\":\"1.3.6.1.2.1.4.24.5.1\",\"pid\":\"1.3.6.1.2.1.4.24.5\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-create\",\"description\":\"The row status variable, used according to row\\ninstallation and removal conventions.\\n\\nA row entry cannot be modified when the status is\\nmarked as active(1).\",\"index\":[],\"name\":\"inetForwardCidrRouteGroup\",\"objectID\":\"1.3.6.1.2.1.4.24.5.1.4\",\"pid\":\"1.3.6.1.2.1.4.24.5.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The row status variable, used according to row\\ninstallation and removal conventions.\",\"index\":[],\"name\":\"ipForwardCidrRouteGroup\",\"objectID\":\"1.3.6.1.2.1.4.24.5.1.3\",\"pid\":\"1.3.6.1.2.1.4.24.5.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"An alternate routing metric for this route.  The\\nsemantics of this metric are determined by the routing-\\nprotocol specified in the route\'s ipForwardProto value.\\nIf this metric is not used, its value should be set to\\n-1.\",\"index\":[],\"name\":\"ipForwardMultiPathGroup\",\"objectID\":\"1.3.6.1.2.1.4.24.5.1.2\",\"pid\":\"1.3.6.1.2.1.4.24.5.1\",\"status\":\"obsolete\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"},{\"access\":\"read-create\",\"description\":\"The row status variable, used according to row\\ninstallation and removal conventions.\\n\\nA row entry cannot be modified when the status is\\nmarked as active(1).\",\"index\":[],\"name\":\"ipForwardCompliances\",\"objectID\":\"1.3.6.1.2.1.4.24.5.2\",\"pid\":\"1.3.6.1.2.1.4.24.5\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-create\",\"description\":\"The row status variable, used according to row\\ninstallation and removal conventions.\\n\\nA row entry cannot be modified when the status is\\nmarked as active(1).\",\"index\":[],\"name\":\"ipForwardFullCompliance\",\"objectID\":\"1.3.6.1.2.1.4.24.5.2.3\",\"pid\":\"1.3.6.1.2.1.4.24.5.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The row status variable, used according to row\\ninstallation and removal conventions.\\n\\nA row entry cannot be modified when the status is\\nmarked as active(1).\",\"index\":[],\"name\":\"ipForwardReadOnlyCompliance\",\"objectID\":\"1.3.6.1.2.1.4.24.5.2.4\",\"pid\":\"1.3.6.1.2.1.4.24.5.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The row status variable, used according to row\\ninstallation and removal conventions.\",\"index\":[],\"name\":\"ipForwardCompliance\",\"objectID\":\"1.3.6.1.2.1.4.24.5.2.1\",\"pid\":\"1.3.6.1.2.1.4.24.5.2\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"An alternate routing metric for this route.  The\\nsemantics of this metric are determined by the routing-\\nprotocol specified in the route\'s ipForwardProto value.\\nIf this metric is not used, its value should be set to\\n-1.\",\"index\":[],\"name\":\"ipForwardOldCompliance\",\"objectID\":\"1.3.6.1.2.1.4.24.5.2.2\",\"pid\":\"1.3.6.1.2.1.4.24.5.2\",\"status\":\"obsolete\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"},{\"access\":\"read-only\",\"description\":\"The number of current ipCidrRouteTable entries that are\\nnot invalid.  This object is deprecated in favor of\\ninetCidrRouteNumber and the inetCidrRouteTable.\",\"index\":[],\"name\":\"ipCidrRouteNumber\",\"objectID\":\"1.3.6.1.2.1.4.24.3\",\"pid\":\"1.3.6.1.2.1.4.24\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"This entity\'s IP Routing table.  This table has been\\ndeprecated in favor of the IP version neutral\\ninetCidrRouteTable.\",\"index\":[],\"name\":\"ipCidrRouteTable\",\"objectID\":\"1.3.6.1.2.1.4.24.4\",\"pid\":\"1.3.6.1.2.1.4.24\",\"status\":\"deprecated\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"A particular route to a particular destination, under a\\n\\nparticular policy.\",\"index\":[\"1.3.6.1.2.1.4.24.4.1.1\",\"1.3.6.1.2.1.4.24.4.1.2\",\"1.3.6.1.2.1.4.24.4.1.3\",\"1.3.6.1.2.1.4.24.4.1.4\"],\"name\":\"ipCidrRouteEntry\",\"objectID\":\"1.3.6.1.2.1.4.24.4.1\",\"pid\":\"1.3.6.1.2.1.4.24.4\",\"status\":\"deprecated\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The destination IP address of this route.\\n\\nThis object may not take a Multicast (Class D) address\\nvalue.\\n\\nAny assignment (implicit or otherwise) of an instance\\nof this object to a value x must be rejected if the\\nbitwise logical-AND of x with the value of the\\ncorresponding instance of the ipCidrRouteMask object is\\nnot equal to x.\",\"index\":[],\"name\":\"ipCidrRouteDest\",\"objectID\":\"1.3.6.1.2.1.4.24.4.1.1\",\"pid\":\"1.3.6.1.2.1.4.24.4.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"Indicate the mask to be logical-ANDed with the\\ndestination address before being compared to the value\\nin the ipCidrRouteDest field.  For those systems that\\ndo not support arbitrary subnet masks, an agent\\nconstructs the value of the ipCidrRouteMask by\\nreference to the IP Address Class.\\n\\nAny assignment (implicit or otherwise) of an instance\\nof this object to a value x must be rejected if the\\nbitwise logical-AND of x with the value of the\\ncorresponding instance of the ipCidrRouteDest object is\\nnot equal to ipCidrRouteDest.\",\"index\":[],\"name\":\"ipCidrRouteMask\",\"objectID\":\"1.3.6.1.2.1.4.24.4.1.2\",\"pid\":\"1.3.6.1.2.1.4.24.4.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The policy specifier is the IP TOS Field.  The encoding\\nof IP TOS is as specified by the following convention.\\nZero indicates the default path if no more specific\\npolicy applies.\\n\\n+-----+-----+-----+-----+-----+-----+-----+-----+\\n|                 |                       |     |\\n|   PRECEDENCE    |    TYPE OF SERVICE    |  0  |\\n|                 |                       |     |\\n+-----+-----+-----+-----+-----+-----+-----+-----+\\n\\n             IP TOS                IP TOS\\n   Field     Policy      Field     Policy\\n   Contents    Code      Contents    Code\\n   0 0 0 0  ==>   0      0 0 0 1  ==>   2\\n   0 0 1 0  ==>   4      0 0 1 1  ==>   6\\n   0 1 0 0  ==>   8      0 1 0 1  ==>  10\\n   0 1 1 0  ==>  12      0 1 1 1  ==>  14\\n   1 0 0 0  ==>  16      1 0 0 1  ==>  18\\n   1 0 1 0  ==>  20      1 0 1 1  ==>  22\\n\\n   1 1 0 0  ==>  24      1 1 0 1  ==>  26\\n   1 1 1 0  ==>  28      1 1 1 1  ==>  30\",\"index\":[],\"name\":\"ipCidrRouteTos\",\"objectID\":\"1.3.6.1.2.1.4.24.4.1.3\",\"pid\":\"1.3.6.1.2.1.4.24.4.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"On remote routes, the address of the next system en\\nroute; Otherwise, 0.0.0.0.\",\"index\":[],\"name\":\"ipCidrRouteNextHop\",\"objectID\":\"1.3.6.1.2.1.4.24.4.1.4\",\"pid\":\"1.3.6.1.2.1.4.24.4.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The ifIndex value that identifies the local interface\\nthrough which the next hop of this route should be\\nreached.\",\"index\":[],\"name\":\"ipCidrRouteIfIndex\",\"objectID\":\"1.3.6.1.2.1.4.24.4.1.5\",\"pid\":\"1.3.6.1.2.1.4.24.4.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The type of route.  Note that local(3) refers to a\\nroute for which the next hop is the final destination;\\nremote(4) refers to a route for which the next hop is\\nnot the final destination.\\n\\nRoutes that do not result in traffic forwarding or\\nrejection should not be displayed, even if the\\nimplementation keeps them stored internally.\\n\\nreject (2) refers to a route that, if matched,\\ndiscards the message as unreachable.  This is used in\\nsome protocols as a means of correctly aggregating\\nroutes.\",\"index\":[],\"name\":\"ipCidrRouteType\",\"objectID\":\"1.3.6.1.2.1.4.24.4.1.6\",\"pid\":\"1.3.6.1.2.1.4.24.4.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The routing mechanism via which this route was learned.\\nInclusion of values for gateway routing protocols is\\nnot intended to imply that hosts should support those\\nprotocols.\",\"index\":[],\"name\":\"ipCidrRouteProto\",\"objectID\":\"1.3.6.1.2.1.4.24.4.1.7\",\"pid\":\"1.3.6.1.2.1.4.24.4.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of seconds since this route was last updated\\nor otherwise determined to be correct.  Note that no\\nsemantics of `too old\' can be implied, except through\\nknowledge of the routing protocol by which the route\\nwas learned.\",\"index\":[],\"name\":\"ipCidrRouteAge\",\"objectID\":\"1.3.6.1.2.1.4.24.4.1.8\",\"pid\":\"1.3.6.1.2.1.4.24.4.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"A reference to MIB definitions specific to the\\nparticular routing protocol that is responsible for\\nthis route, as determined by the value specified in the\\nroute\'s ipCidrRouteProto value.  If this information is\\nnot present, its value should be set to the OBJECT\\nIDENTIFIER { 0 0 }, which is a syntactically valid\\nobject identifier, and any implementation conforming to\\nASN.1 and the Basic Encoding Rules must be able to\\ngenerate and recognize this value.\",\"index\":[],\"name\":\"ipCidrRouteInfo\",\"objectID\":\"1.3.6.1.2.1.4.24.4.1.9\",\"pid\":\"1.3.6.1.2.1.4.24.4.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"OBJECT IDENTIFIER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The Autonomous System Number of the Next Hop.  The\\nsemantics of this object are determined by the routing-\\nprotocol specified in the route\'s ipCidrRouteProto\\nvalue.  When this object is unknown or not relevant, its\\nvalue should be set to zero.\",\"index\":[],\"name\":\"ipCidrRouteNextHopAS\",\"objectID\":\"1.3.6.1.2.1.4.24.4.1.10\",\"pid\":\"1.3.6.1.2.1.4.24.4.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The primary routing metric for this route.  The\\nsemantics of this metric are determined by the routing-\\nprotocol specified in the route\'s ipCidrRouteProto\\nvalue.  If this metric is not used, its value should be\\nset to -1.\",\"index\":[],\"name\":\"ipCidrRouteMetric1\",\"objectID\":\"1.3.6.1.2.1.4.24.4.1.11\",\"pid\":\"1.3.6.1.2.1.4.24.4.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"An alternate routing metric for this route.  The\\nsemantics of this metric are determined by the routing-\\nprotocol specified in the route\'s ipCidrRouteProto\\nvalue.  If this metric is not used, its value should be\\n\\nset to -1.\",\"index\":[],\"name\":\"ipCidrRouteMetric2\",\"objectID\":\"1.3.6.1.2.1.4.24.4.1.12\",\"pid\":\"1.3.6.1.2.1.4.24.4.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"An alternate routing metric for this route.  The\\nsemantics of this metric are determined by the routing-\\nprotocol specified in the route\'s ipCidrRouteProto\\nvalue.  If this metric is not used, its value should be\\nset to -1.\",\"index\":[],\"name\":\"ipCidrRouteMetric3\",\"objectID\":\"1.3.6.1.2.1.4.24.4.1.13\",\"pid\":\"1.3.6.1.2.1.4.24.4.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"An alternate routing metric for this route.  The\\nsemantics of this metric are determined by the routing-\\nprotocol specified in the route\'s ipCidrRouteProto\\nvalue.  If this metric is not used, its value should be\\nset to -1.\",\"index\":[],\"name\":\"ipCidrRouteMetric4\",\"objectID\":\"1.3.6.1.2.1.4.24.4.1.14\",\"pid\":\"1.3.6.1.2.1.4.24.4.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"An alternate routing metric for this route.  The\\nsemantics of this metric are determined by the routing-\\nprotocol specified in the route\'s ipCidrRouteProto\\nvalue.  If this metric is not used, its value should be\\nset to -1.\",\"index\":[],\"name\":\"ipCidrRouteMetric5\",\"objectID\":\"1.3.6.1.2.1.4.24.4.1.15\",\"pid\":\"1.3.6.1.2.1.4.24.4.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The row status variable, used according to row\\ninstallation and removal conventions.\",\"index\":[],\"name\":\"ipCidrRouteStatus\",\"objectID\":\"1.3.6.1.2.1.4.24.4.1.16\",\"pid\":\"1.3.6.1.2.1.4.24.4.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"},{\"access\":\"read-only\",\"description\":\"The number of current ipForwardTable entries that are\\nnot invalid.\",\"index\":[],\"name\":\"ipForwardNumber\",\"objectID\":\"1.3.6.1.2.1.4.24.1\",\"pid\":\"1.3.6.1.2.1.4.24\",\"status\":\"obsolete\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"This entity\'s IP Routing table.\",\"index\":[],\"name\":\"ipForwardTable\",\"objectID\":\"1.3.6.1.2.1.4.24.2\",\"pid\":\"1.3.6.1.2.1.4.24\",\"status\":\"obsolete\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"A particular route to a particular destination, under a\\nparticular policy.\",\"index\":[\"1.3.6.1.2.1.4.24.2.1.1\",\"1.3.6.1.2.1.4.24.2.1.7\",\"1.3.6.1.2.1.4.24.2.1.3\",\"1.3.6.1.2.1.4.24.2.1.4\"],\"name\":\"ipForwardEntry\",\"objectID\":\"1.3.6.1.2.1.4.24.2.1\",\"pid\":\"1.3.6.1.2.1.4.24.2\",\"status\":\"obsolete\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The destination IP address of this route.  An entry\\nwith a value of 0.0.0.0 is considered a default route.\\n\\nThis object may not take a Multicast (Class D) address\\nvalue.\\n\\nAny assignment (implicit or otherwise) of an instance\\nof this object to a value x must be rejected if the\\nbitwise logical-AND of x with the value of the\\ncorresponding instance of the ipForwardMask object is\\nnot equal to x.\",\"index\":[],\"name\":\"ipForwardDest\",\"objectID\":\"1.3.6.1.2.1.4.24.2.1.1\",\"pid\":\"1.3.6.1.2.1.4.24.2.1\",\"status\":\"obsolete\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"Indicate the mask to be logical-ANDed with the\\ndestination address before being compared to the value\\nin the ipForwardDest field.  For those systems that do\\nnot support arbitrary subnet masks, an agent constructs\\nthe value of the ipForwardMask by reference to the IP\\nAddress Class.\\n\\nAny assignment (implicit or otherwise) of an instance\\nof this object to a value x must be rejected if the\\nbitwise logical-AND of x with the value of the\\ncorresponding instance of the ipForwardDest object is\\nnot equal to ipForwardDest.\",\"index\":[],\"name\":\"ipForwardMask\",\"objectID\":\"1.3.6.1.2.1.4.24.2.1.2\",\"pid\":\"1.3.6.1.2.1.4.24.2.1\",\"status\":\"obsolete\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The general set of conditions that would cause\\nthe selection of one multipath route (set of\\nnext hops for a given destination) is referred\\nto as \'policy\'.\\n\\nUnless the mechanism indicated by ipForwardProto\\nspecifies otherwise, the policy specifier is\\nthe IP TOS Field.  The encoding of IP TOS is as\\nspecified by the following convention.  Zero\\nindicates the default path if no more specific\\npolicy applies.\\n\\n+-----+-----+-----+-----+-----+-----+-----+-----+\\n|                 |                       |     |\\n|   PRECEDENCE    |    TYPE OF SERVICE    |  0  |\\n|                 |                       |     |\\n+-----+-----+-----+-----+-----+-----+-----+-----+\\n\\n             IP TOS                IP TOS\\n   Field     Policy      Field     Policy\\n   Contents    Code      Contents    Code\\n   0 0 0 0  ==>   0      0 0 0 1  ==>   2\\n   0 0 1 0  ==>   4      0 0 1 1  ==>   6\\n   0 1 0 0  ==>   8      0 1 0 1  ==>  10\\n   0 1 1 0  ==>  12      0 1 1 1  ==>  14\\n   1 0 0 0  ==>  16      1 0 0 1  ==>  18\\n   1 0 1 0  ==>  20      1 0 1 1  ==>  22\\n   1 1 0 0  ==>  24      1 1 0 1  ==>  26\\n   1 1 1 0  ==>  28      1 1 1 1  ==>  30\\n\\nProtocols defining \'policy\' otherwise must either\\ndefine a set of values that are valid for\\nthis object or must implement an integer-instanced\\npolicy table for which this object\'s\\nvalue acts as an index.\",\"index\":[],\"name\":\"ipForwardPolicy\",\"objectID\":\"1.3.6.1.2.1.4.24.2.1.3\",\"pid\":\"1.3.6.1.2.1.4.24.2.1\",\"status\":\"obsolete\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"On remote routes, the address of the next system en\\nroute; otherwise, 0.0.0.0.\",\"index\":[],\"name\":\"ipForwardNextHop\",\"objectID\":\"1.3.6.1.2.1.4.24.2.1.4\",\"pid\":\"1.3.6.1.2.1.4.24.2.1\",\"status\":\"obsolete\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The ifIndex value that identifies the local interface\\nthrough which the next hop of this route should be\\nreached.\",\"index\":[],\"name\":\"ipForwardIfIndex\",\"objectID\":\"1.3.6.1.2.1.4.24.2.1.5\",\"pid\":\"1.3.6.1.2.1.4.24.2.1\",\"status\":\"obsolete\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The type of route.  Note that local(3) refers to a\\nroute for which the next hop is the final destination;\\nremote(4) refers to a route for which the next hop is\\nnot the final destination.\\n\\nSetting this object to the value invalid(2) has the\\neffect of invalidating the corresponding entry in the\\nipForwardTable object.  That is, it effectively\\ndisassociates the destination identified with said\\nentry from the route identified with said entry.  It is\\nan implementation-specific matter as to whether the\\nagent removes an invalidated entry from the table.\\nAccordingly, management stations must be prepared to\\nreceive tabular information from agents that\\ncorresponds to entries not currently in use.  Proper\\ninterpretation of such entries requires examination of\\nthe relevant ipForwardType object.\",\"index\":[],\"name\":\"ipForwardType\",\"objectID\":\"1.3.6.1.2.1.4.24.2.1.6\",\"pid\":\"1.3.6.1.2.1.4.24.2.1\",\"status\":\"obsolete\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The routing mechanism via which this route was learned.\\nInclusion of values for gateway routing protocols is\\nnot intended to imply that hosts should support those\\nprotocols.\",\"index\":[],\"name\":\"ipForwardProto\",\"objectID\":\"1.3.6.1.2.1.4.24.2.1.7\",\"pid\":\"1.3.6.1.2.1.4.24.2.1\",\"status\":\"obsolete\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of seconds since this route was last updated\\nor otherwise determined to be correct.  Note that no\\nsemantics of `too old\' can be implied except through\\nknowledge of the routing protocol by which the route\\nwas learned.\",\"index\":[],\"name\":\"ipForwardAge\",\"objectID\":\"1.3.6.1.2.1.4.24.2.1.8\",\"pid\":\"1.3.6.1.2.1.4.24.2.1\",\"status\":\"obsolete\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"A reference to MIB definitions specific to the\\nparticular routing protocol that is responsible for\\nthis route, as determined by the value specified in the\\nroute\'s ipForwardProto value.  If this information is\\nnot present, its value should be set to the OBJECT\\nIDENTIFIER { 0 0 }, which is a syntactically valid\\nobject identifier, and any implementation conforming to\\nASN.1 and the Basic Encoding Rules must be able to\\ngenerate and recognize this value.\",\"index\":[],\"name\":\"ipForwardInfo\",\"objectID\":\"1.3.6.1.2.1.4.24.2.1.9\",\"pid\":\"1.3.6.1.2.1.4.24.2.1\",\"status\":\"obsolete\",\"subTree\":[],\"syntax\":\"OBJECT IDENTIFIER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The Autonomous System Number of the Next Hop.  When\\nthis is unknown or not relevant to the protocol\\nindicated by ipForwardProto, zero.\",\"index\":[],\"name\":\"ipForwardNextHopAS\",\"objectID\":\"1.3.6.1.2.1.4.24.2.1.10\",\"pid\":\"1.3.6.1.2.1.4.24.2.1\",\"status\":\"obsolete\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The primary routing metric for this route.  The\\nsemantics of this metric are determined by the routing-\\nprotocol specified in the route\'s ipForwardProto value.\\nIf this metric is not used, its value should be set to\\n-1.\",\"index\":[],\"name\":\"ipForwardMetric1\",\"objectID\":\"1.3.6.1.2.1.4.24.2.1.11\",\"pid\":\"1.3.6.1.2.1.4.24.2.1\",\"status\":\"obsolete\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"An alternate routing metric for this route.  The\\nsemantics of this metric are determined by the routing-\\nprotocol specified in the route\'s ipForwardProto value.\\nIf this metric is not used, its value should be set to\\n-1.\",\"index\":[],\"name\":\"ipForwardMetric2\",\"objectID\":\"1.3.6.1.2.1.4.24.2.1.12\",\"pid\":\"1.3.6.1.2.1.4.24.2.1\",\"status\":\"obsolete\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"An alternate routing metric for this route.  The\\nsemantics of this metric are determined by the routing-\\nprotocol specified in the route\'s ipForwardProto value.\\nIf this metric is not used, its value should be set to\\n-1.\",\"index\":[],\"name\":\"ipForwardMetric3\",\"objectID\":\"1.3.6.1.2.1.4.24.2.1.13\",\"pid\":\"1.3.6.1.2.1.4.24.2.1\",\"status\":\"obsolete\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"An alternate routing metric for this route.  The\\nsemantics of this metric are determined by the routing-\\nprotocol specified in the route\'s ipForwardProto value.\\nIf this metric is not used, its value should be set to\\n-1.\",\"index\":[],\"name\":\"ipForwardMetric4\",\"objectID\":\"1.3.6.1.2.1.4.24.2.1.14\",\"pid\":\"1.3.6.1.2.1.4.24.2.1\",\"status\":\"obsolete\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"An alternate routing metric for this route.  The\\nsemantics of this metric are determined by the routing-\\nprotocol specified in the route\'s ipForwardProto value.\\nIf this metric is not used, its value should be set to\\n-1.\",\"index\":[],\"name\":\"ipForwardMetric5\",\"objectID\":\"1.3.6.1.2.1.4.24.2.1.15\",\"pid\":\"1.3.6.1.2.1.4.24.2.1\",\"status\":\"obsolete\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"}],\"type\":\"OBJECT\"}]}');
INSERT INTO `snmp_mib` VALUES (19, 'IP-MIB', 'IP-MIB.txt', , '', '', 1, '2021-09-29 11:58:11', '{\"IP-MIB\":[{\"index\":[],\"name\":\"ipMIB\",\"objectID\":\"1.3.6.1.2.1.48\",\"pid\":\"1.3.6.1.2.1\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The number of output packets for this AF and type.\",\"index\":[],\"name\":\"ipMIBConformance\",\"objectID\":\"1.3.6.1.2.1.48.2\",\"pid\":\"1.3.6.1.2.1.48\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The number of output packets for this AF and type.\",\"index\":[],\"name\":\"ipMIBCompliances\",\"objectID\":\"1.3.6.1.2.1.48.2.1\",\"pid\":\"1.3.6.1.2.1.48.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The number of output packets for this AF and type.\",\"index\":[],\"name\":\"ipMIBCompliance2\",\"objectID\":\"1.3.6.1.2.1.48.2.1.2\",\"pid\":\"1.3.6.1.2.1.48.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of ICMP Address Mask Reply messages sent.\\n\\nThis object has been deprecated, as a new IP version-neutral\\ntable has been added.  It is loosely replaced by a column in\\nthe icmpMsgStatsTable.\",\"index\":[],\"name\":\"ipMIBCompliance\",\"objectID\":\"1.3.6.1.2.1.48.2.1.1\",\"pid\":\"1.3.6.1.2.1.48.2.1\",\"status\":\"deprecated\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"},{\"access\":\"read-only\",\"description\":\"The number of output packets for this AF and type.\",\"index\":[],\"name\":\"ipMIBGroups\",\"objectID\":\"1.3.6.1.2.1.48.2.2\",\"pid\":\"1.3.6.1.2.1.48.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The number of output packets for this AF and type.\",\"index\":[],\"name\":\"ipv4GeneralGroup\",\"objectID\":\"1.3.6.1.2.1.48.2.2.3\",\"pid\":\"1.3.6.1.2.1.48.2.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJEC