INSERT INTO `snmp_mib` VALUES (27, 'MTA-MIB', 'MTA-MIB.txt', , '', '', 1, '2021-09-29 11:59:57', '{\"MTA-MIB\":[{\"index\":[],\"name\":\"mta\",\"objectID\":\"1.3.6.1.2.1.28\",\"pid\":\"1.3.6.1.2.1\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"The table holding information specific to an MTA.\",\"index\":[],\"name\":\"mtaTable\",\"objectID\":\"1.3.6.1.2.1.28.1\",\"pid\":\"1.3.6.1.2.1.28\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"The entry associated with each MTA.\",\"index\":[\"1.3.6.1.2.1.27.1.1.1\"],\"name\":\"mtaEntry\",\"objectID\":\"1.3.6.1.2.1.28.1.1\",\"pid\":\"1.3.6.1.2.1.28.1\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The number of messages received since MTA initialization.\\nThis includes messages transmitted to this MTA from other\\nMTAs as well as messages that have been submitted to the\\nMTA directly by end-users or applications.\",\"index\":[],\"name\":\"mtaReceivedMessages\",\"objectID\":\"1.3.6.1.2.1.28.1.1.1\",\"pid\":\"1.3.6.1.2.1.28.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of messages currently stored in the MTA.\\nThis includes messages that are awaiting transmission to\\nsome other MTA or are waiting for delivery to an end-user\\nor application.\",\"index\":[],\"name\":\"mtaStoredMessages\",\"objectID\":\"1.3.6.1.2.1.28.1.1.2\",\"pid\":\"1.3.6.1.2.1.28.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of messages transmitted since MTA initialization.\\nThis includes messages that were transmitted to some other\\nMTA or are waiting for delivery to an end-user or\\napplication.\",\"index\":[],\"name\":\"mtaTransmittedMessages\",\"objectID\":\"1.3.6.1.2.1.28.1.1.3\",\"pid\":\"1.3.6.1.2.1.28.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total volume of messages received since MTA\\ninitialization, measured in kilo-octets.  This volume should\\ninclude all transferred data that is logically above the mail\\ntransport protocol level.  For example, an SMTP-based MTA\\nshould use the number of kilo-octets in the message header\\nand body, while an X.400-based MTA should use the number of\\nkilo-octets of P2 data.  This includes messages transmitted\\nto this MTA from other MTAs as well as messages that have\\nbeen submitted to the MTA directly by end-users or\\napplications.\",\"index\":[],\"name\":\"mtaReceivedVolume\",\"objectID\":\"1.3.6.1.2.1.28.1.1.4\",\"pid\":\"1.3.6.1.2.1.28.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total volume of messages currently stored in the MTA,\\nmeasured in kilo-octets.  This volume should include all\\nstored data that is logically above the mail transport\\nprotocol level.  For example, an SMTP-based MTA should\\nuse the number of kilo-octets in the message header and\\nbody, while an X.400-based MTA would use the number of\\nkilo-octets of P2 data.  This includes messages that are\\nawaiting transmission to some other MTA or are waiting\\nfor delivery to an end-user or application.\",\"index\":[],\"name\":\"mtaStoredVolume\",\"objectID\":\"1.3.6.1.2.1.28.1.1.5\",\"pid\":\"1.3.6.1.2.1.28.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total volume of messages transmitted since MTA\\ninitialization, measured in kilo-octets.  This volume should\\ninclude all transferred data that is logically above the mail\\ntransport protocol level.  For example, an SMTP-based MTA\\nshould use the number of kilo-octets in the message header\\nand body, while an X.400-based MTA should use the number of\\nkilo-octets of P2 data.  This includes messages that were\\ntransmitted to some other MTA or are waiting for delivery\\nto an end-user or application.\",\"index\":[],\"name\":\"mtaTransmittedVolume\",\"objectID\":\"1.3.6.1.2.1.28.1.1.6\",\"pid\":\"1.3.6.1.2.1.28.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of recipients specified in all messages\\nreceived since MTA initialization.  Recipients this MTA\\nhas no responsibility for, i.e. inactive envelope\\nrecipients or ones referred to in message headers,\\nshould not be counted even if information about such\\nrecipients is available.  This includes messages\\ntransmitted to this MTA from other MTAs as well as\\nmessages that have been submitted to the MTA directly\\nby end-users or applications.\",\"index\":[],\"name\":\"mtaReceivedRecipients\",\"objectID\":\"1.3.6.1.2.1.28.1.1.7\",\"pid\":\"1.3.6.1.2.1.28.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of recipients specified in all messages\\ncurrently stored in the MTA.  Recipients this MTA has no\\nresponsibility for, i.e. inactive envelope recipients or\\nones referred to in message headers, should not be\\ncounted.  This includes messages that are awaiting\\ntransmission to some other MTA or are waiting for\\ndelivery to an end-user or application.\",\"index\":[],\"name\":\"mtaStoredRecipients\",\"objectID\":\"1.3.6.1.2.1.28.1.1.8\",\"pid\":\"1.3.6.1.2.1.28.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of recipients specified in all messages\\ntransmitted since MTA initialization.  Recipients this\\nMTA had no responsibility for, i.e. inactive envelope\\nrecipients or ones referred to in message headers,\\nshould not be counted.  This includes messages that were\\ntransmitted to some other MTA or are waiting for\\ndelivery to an end-user or application.\",\"index\":[],\"name\":\"mtaTransmittedRecipients\",\"objectID\":\"1.3.6.1.2.1.28.1.1.9\",\"pid\":\"1.3.6.1.2.1.28.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of messages that have been successfully\\nconverted from one form to another since MTA\\ninitialization.\",\"index\":[],\"name\":\"mtaSuccessfulConvertedMessages\",\"objectID\":\"1.3.6.1.2.1.28.1.1.10\",\"pid\":\"1.3.6.1.2.1.28.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of messages for which an unsuccessful\\nattempt was made to convert them from one form to\\nanother since MTA initialization.\",\"index\":[],\"name\":\"mtaFailedConvertedMessages\",\"objectID\":\"1.3.6.1.2.1.28.1.1.11\",\"pid\":\"1.3.6.1.2.1.28.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"A message loop is defined as a situation where the MTA\\ndecides that a given message will never be delivered to\\none or more recipients and instead will continue to\\nloop endlessly through one or more MTAs.  This variable\\ncounts the number of times the MTA has detected such a\\nsituation since MTA initialization. Note that the\\nmechanism MTAs use to detect loops (e.g., trace field\\ncounting, count of references to this MTA in a trace\\nfield, examination of DNS or other directory information,\\netc.), the level at which loops are detected (e.g., per\\nmessage, per recipient, per directory entry, etc.), and\\nthe handling of a loop once it is detected (e.g., looping\\n\\nmessages are held, looping messages are bounced or sent\\nto the postmaster, messages that the MTA knows will loop\\nwon\'t be accepted, etc.) vary widely from one MTA to the\\nnext and cannot be inferred from this variable.\",\"index\":[],\"name\":\"mtaLoopsDetected\",\"objectID\":\"1.3.6.1.2.1.28.1.1.12\",\"pid\":\"1.3.6.1.2.1.28.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"},{\"access\":\"not-accessible\",\"description\":\"The table holding information specific to each MTA group.\",\"index\":[],\"name\":\"mtaGroupTable\",\"objectID\":\"1.3.6.1.2.1.28.2\",\"pid\":\"1.3.6.1.2.1.28\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"The entry associated with each MTA group.\",\"index\":[\"1.3.6.1.2.1.27.1.1.1\",\"1.3.6.1.2.1.28.2.1.1\"],\"name\":\"mtaGroupEntry\",\"objectID\":\"1.3.6.1.2.1.28.2.1\",\"pid\":\"1.3.6.1.2.1.28.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"The index associated with a group for a given MTA.\",\"index\":[],\"name\":\"mtaGroupIndex\",\"objectID\":\"1.3.6.1.2.1.28.2.1.1\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of messages received to this group since\\ngroup creation.\",\"index\":[],\"name\":\"mtaGroupReceivedMessages\",\"objectID\":\"1.3.6.1.2.1.28.2.1.2\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of messages rejected by this group since\\ngroup creation.\",\"index\":[],\"name\":\"mtaGroupRejectedMessages\",\"objectID\":\"1.3.6.1.2.1.28.2.1.3\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of messages currently stored in this\\ngroup\'s queue.\",\"index\":[],\"name\":\"mtaGroupStoredMessages\",\"objectID\":\"1.3.6.1.2.1.28.2.1.4\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of messages transmitted by this group since\\ngroup creation.\",\"index\":[],\"name\":\"mtaGroupTransmittedMessages\",\"objectID\":\"1.3.6.1.2.1.28.2.1.5\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total volume of messages received to this group since\\ngroup creation, measured in kilo-octets.  This volume\\nshould include all transferred data that is logically above\\nthe mail transport protocol level.  For example, an\\nSMTP-based MTA should use the number of kilo-octets in the\\nmessage header and body, while an X.400-based MTA should use\\nthe number of kilo-octets of P2 data.\",\"index\":[],\"name\":\"mtaGroupReceivedVolume\",\"objectID\":\"1.3.6.1.2.1.28.2.1.6\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total volume of messages currently stored in this\\ngroup\'s queue, measured in kilo-octets.  This volume should\\ninclude all stored data that is logically above the mail\\ntransport protocol level.  For example, an SMTP-based\\nMTA should use the number of kilo-octets in the message\\nheader and body, while an X.400-based MTA would use the\\nnumber of kilo-octets of P2 data.\",\"index\":[],\"name\":\"mtaGroupStoredVolume\",\"objectID\":\"1.3.6.1.2.1.28.2.1.7\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total volume of messages transmitted by this group\\nsince group creation, measured in kilo-octets.  This\\nvolume should include all transferred data that is logically\\nabove the mail transport protocol level.  For example, an\\nSMTP-based MTA should use the number of kilo-octets in the\\nmessage header and body, while an X.400-based MTA should use\\nthe number of kilo-octets of P2 data.\",\"index\":[],\"name\":\"mtaGroupTransmittedVolume\",\"objectID\":\"1.3.6.1.2.1.28.2.1.8\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of recipients specified in all messages\\nreceived to this group since group creation.\\nRecipients this MTA has no responsibility for should not\\nbe counted.\",\"index\":[],\"name\":\"mtaGroupReceivedRecipients\",\"objectID\":\"1.3.6.1.2.1.28.2.1.9\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of recipients specified in all messages\\ncurrently stored in this group\'s queue.  Recipients this\\nMTA has no responsibility for should not be counted.\",\"index\":[],\"name\":\"mtaGroupStoredRecipients\",\"objectID\":\"1.3.6.1.2.1.28.2.1.10\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of recipients specified in all messages\\ntransmitted by this group since group creation.\\nRecipients this MTA had no responsibility for should not\\nbe counted.\",\"index\":[],\"name\":\"mtaGroupTransmittedRecipients\",\"objectID\":\"1.3.6.1.2.1.28.2.1.11\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"Time since the oldest message in this group\'s queue was\\n\\nplaced in the queue.\",\"index\":[],\"name\":\"mtaGroupOldestMessageStored\",\"objectID\":\"1.3.6.1.2.1.28.2.1.12\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of current associations to the group, where the\\ngroup is the responder.\",\"index\":[],\"name\":\"mtaGroupInboundAssociations\",\"objectID\":\"1.3.6.1.2.1.28.2.1.13\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of current associations to the group, where the\\ngroup is the initiator.\",\"index\":[],\"name\":\"mtaGroupOutboundAssociations\",\"objectID\":\"1.3.6.1.2.1.28.2.1.14\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of associations to the group since\\ngroup creation, where the MTA was the responder.\",\"index\":[],\"name\":\"mtaGroupAccumulatedInboundAssociations\",\"objectID\":\"1.3.6.1.2.1.28.2.1.15\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of associations from the group since\\ngroup creation, where the MTA was the initiator.\",\"index\":[],\"name\":\"mtaGroupAccumulatedOutboundAssociations\",\"objectID\":\"1.3.6.1.2.1.28.2.1.16\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"Time since the last time that this group had an active\\ninbound association for purposes of message reception.\",\"index\":[],\"name\":\"mtaGroupLastInboundActivity\",\"objectID\":\"1.3.6.1.2.1.28.2.1.17\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"Time since the last time that this group had a\\nsuccessful outbound association for purposes of\\nmessage delivery.\",\"index\":[],\"name\":\"mtaGroupLastOutboundActivity\",\"objectID\":\"1.3.6.1.2.1.28.2.1.18\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"Time since the last time that this group attempted\\nto make an outbound association for purposes of\\nmessage delivery.\",\"index\":[],\"name\":\"mtaGroupLastOutboundAssociationAttempt\",\"objectID\":\"1.3.6.1.2.1.28.2.1.34\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of inbound associations the group has\\nrejected, since group creation.  Rejected associations\\nare not counted in the accumulated association totals.\",\"index\":[],\"name\":\"mtaGroupRejectedInboundAssociations\",\"objectID\":\"1.3.6.1.2.1.28.2.1.19\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number associations where the group was the\\ninitiator and association establishment has failed,\\nsince group creation.  Failed associations are\\nnot counted in the accumulated association totals.\",\"index\":[],\"name\":\"mtaGroupFailedOutboundAssociations\",\"objectID\":\"1.3.6.1.2.1.28.2.1.20\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The failure reason, if any, for the last association this\\ngroup refused to respond to. If no association attempt\\n\\nhas been made since the MTA was initialized the value\\nshould be \'never\'.\",\"index\":[],\"name\":\"mtaGroupInboundRejectionReason\",\"objectID\":\"1.3.6.1.2.1.28.2.1.21\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The failure reason, if any, for the last association attempt\\nthis group initiated. If no association attempt has been\\nmade since the MTA was initialized the value should be\\n\'never\'.\",\"index\":[],\"name\":\"mtaGroupOutboundConnectFailureReason\",\"objectID\":\"1.3.6.1.2.1.28.2.1.22\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The amount of time until this group is next scheduled to\\nattempt to make an association.\",\"index\":[],\"name\":\"mtaGroupScheduledRetry\",\"objectID\":\"1.3.6.1.2.1.28.2.1.23\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"An identification of the protocol being used by this group.\\nFor an group employing OSI protocols, this will be the\\nApplication Context.    For Internet applications, OID\\nvalues of the form {applTCPProtoID port} or {applUDPProtoID\\nport} are used for TCP-based and UDP-based protocols,\\nrespectively. In either case \'port\' corresponds to the\\nprimary port number being used by the protocol. The\\nusual IANA procedures may be used to register ports for\\nnew protocols. applTCPProtoID and applUDPProtoID are\\ndefined in the NETWORK-SERVICES-MIB, RFC 2788.\",\"index\":[],\"name\":\"mtaGroupMailProtocol\",\"objectID\":\"1.3.6.1.2.1.28.2.1.24\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OBJECT IDENTIFIER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"A descriptive name for the group. If this group connects to\\na single remote MTA this should be the name of that MTA. If\\n\\nthis in turn is an Internet MTA this should be the domain\\nname.  For an OSI MTA it should be the string encoded\\ndistinguished name of the managed object using the format\\ndefined in RFC 2253.  For X.400(1984) MTAs which do not\\nhave a Distinguished Name, the RFC 2156 syntax\\n\'mta in globalid\' used in X400-Received: fields can be\\nused.\",\"index\":[],\"name\":\"mtaGroupName\",\"objectID\":\"1.3.6.1.2.1.28.2.1.25\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of messages that have been successfully\\nconverted from one form to another in this group\\nsince group creation.\",\"index\":[],\"name\":\"mtaGroupSuccessfulConvertedMessages\",\"objectID\":\"1.3.6.1.2.1.28.2.1.26\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of messages for which an unsuccessful\\nattempt was made to convert them from one form to\\nanother in this group since group creation.\",\"index\":[],\"name\":\"mtaGroupFailedConvertedMessages\",\"objectID\":\"1.3.6.1.2.1.28.2.1.27\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"A description of the group\'s purpose.  This information is\\nintended to identify the group in a status display.\",\"index\":[],\"name\":\"mtaGroupDescription\",\"objectID\":\"1.3.6.1.2.1.28.2.1.28\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"A URL pointing to a description of the group.  This\\ninformation is intended to identify and briefly describe\\nthe group in a status display.\",\"index\":[],\"name\":\"mtaGroupURL\",\"objectID\":\"1.3.6.1.2.1.28.2.1.29\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"Time since this group was first created.\",\"index\":[],\"name\":\"mtaGroupCreationTime\",\"objectID\":\"1.3.6.1.2.1.28.2.1.30\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"Describes how this group fits into the hierarchy. A\\npositive value is interpreted as an mtaGroupIndex\\nvalue for some other group whose variables include\\nthose of this group (and usually others). A negative\\nvalue is interpreted as a group collection code: Groups\\nwith common negative hierarchy values comprise one\\nparticular breakdown of MTA activity as a whole. A\\nzero value means that this MIB implementation doesn\'t\\nimplement hierarchy indicators and thus the overall\\ngroup hierarchy cannot be determined.\",\"index\":[],\"name\":\"mtaGroupHierarchy\",\"objectID\":\"1.3.6.1.2.1.28.2.1.31\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"Message ID of the oldest message in the group\'s queue.\\nWhenever possible this should be in the form of an\\nRFC 822 msg-id; X.400 may convert X.400 message\\nidentifiers to this form by following the rules laid\\nout in RFC2156.\",\"index\":[],\"name\":\"mtaGroupOldestMessageId\",\"objectID\":\"1.3.6.1.2.1.28.2.1.32\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"A message loop is defined as a situation where the MTA\\ndecides that a given message will never be delivered to\\none or more recipients and instead will continue to\\nloop endlessly through one or more MTAs.  This variable\\ncounts the number of times the MTA has detected such a\\nsituation in conjunction with something associated with\\n\\nthis group since group creation.  Note that the\\nmechanism MTAs use to detect loops (e.g., trace field\\ncounting, count of references to this MTA in a trace\\nfield, examination of DNS or other directory information,\\netc.), the level at which loops are detected (e.g., per\\nmessage, per recipient, per directory entry, etc.), and\\nthe handling of a loop once it is detected (e.g., looping\\nmessages are held, looping messages are bounced or sent\\nto the postmaster, messages that the MTA knows will loop\\nwon\'t be accepted, etc.) vary widely from one MTA to the\\nnext and cannot be inferred from this variable.\",\"index\":[],\"name\":\"mtaGroupLoopsDetected\",\"objectID\":\"1.3.6.1.2.1.28.2.1.33\",\"pid\":\"1.3.6.1.2.1.28.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"},{\"access\":\"not-accessible\",\"description\":\"The table holding information regarding the associations\\nfor each MTA group.\",\"index\":[],\"name\":\"mtaGroupAssociationTable\",\"objectID\":\"1.3.6.1.2.1.28.3\",\"pid\":\"1.3.6.1.2.1.28\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"The entry holding information regarding the associations\\nfor each MTA group.\",\"index\":[\"1.3.6.1.2.1.27.1.1.1\",\"1.3.6.1.2.1.28.2.1.1\",\"1.3.6.1.2.1.28.3.1.1\"],\"name\":\"mtaGroupAssociationEntry\",\"objectID\":\"1.3.6.1.2.1.28.3.1\",\"pid\":\"1.3.6.1.2.1.28.3\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"Reference into association table to allow correlation of\\nthis group\'s active associations with the association table.\",\"index\":[],\"name\":\"mtaGroupAssociationIndex\",\"objectID\":\"1.3.6.1.2.1.28.3.1.1\",\"pid\":\"1.3.6.1.2.1.28.3.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"},{\"access\":\"not-accessible\",\"description\":\"The table holding information regarding accumulated errors\\nfor each MTA group.\",\"index\":[],\"name\":\"mtaGroupErrorTable\",\"objectID\":\"1.3.6.1.2.1.28.5\",\"pid\":\"1.3.6.1.2.1.28\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"The entry holding information regarding accumulated\\nerrors for each MTA group.\",\"index\":[\"1.3.6.1.2.1.27.1.1.1\",\"1.3.6.1.2.1.28.2.1.1\",\"1.3.6.1.2.1.28.5.1.4\"],\"name\":\"mtaGroupErrorEntry\",\"objectID\":\"1.3.6.1.2.1.28.5.1\",\"pid\":\"1.3.6.1.2.1.28.5\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"Count of the number of errors of a given type that have\\nbeen accumulated in association with a particular group\\nwhile processing incoming messages. In the case of SMTP\\n\\nthese will typically be errors reporting by an SMTP\\nserver to the remote client; in the case of X.400\\nthese will typically be errors encountered while\\nprocessing an incoming message.\",\"index\":[],\"name\":\"mtaGroupInboundErrorCount\",\"objectID\":\"1.3.6.1.2.1.28.5.1.1\",\"pid\":\"1.3.6.1.2.1.28.5.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"Count of the number of errors of a given type that have\\nbeen accumulated in association with a particular group\\nduring internal MTA processing.\",\"index\":[],\"name\":\"mtaGroupInternalErrorCount\",\"objectID\":\"1.3.6.1.2.1.28.5.1.2\",\"pid\":\"1.3.6.1.2.1.28.5.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"Count of the number of errors of a given type that have\\nbeen accumulated in association with a particular group\'s\\noutbound connection activities. In the case of an SMTP\\nclient these will typically be errors reported while\\nattempting to contact or while communicating with the\\nremote SMTP server. In the case of X.400 these will\\ntypically be errors encountered while constructing\\nor attempting to deliver an outgoing message.\",\"index\":[],\"name\":\"mtaGroupOutboundErrorCount\",\"objectID\":\"1.3.6.1.2.1.28.5.1.3\",\"pid\":\"1.3.6.1.2.1.28.5.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"An index capable of representing an Enhanced Mail System\\nStatus Code.  Enhanced Mail System Status Codes are\\ndefined in RFC 1893.  These codes have the form\\n\\n    class.subject.detail\\n\\nHere \'class\' is either 2, 4, or 5 and both \'subject\' and\\n\'detail\'  are integers in the range 0..999. Given a status\\ncode the corresponding index value is defined to be\\n((class * 1000) + subject) * 1000 + detail.  Both SMTP\\nerror response codes and X.400 reason and diagnostic codes\\ncan be mapped into these codes, resulting in a namespace\\n\\ncapable of describing most error conditions a mail system\\nencounters in a generic yet detailed way.\",\"index\":[],\"name\":\"mtaStatusCode\",\"objectID\":\"1.3.6.1.2.1.28.5.1.4\",\"pid\":\"1.3.6.1.2.1.28.5.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"},{\"access\":\"not-accessible\",\"description\":\"An index capable of representing an Enhanced Mail System\\nStatus Code.  Enhanced Mail System Status Codes are\\ndefined in RFC 1893.  These codes have the form\\n\\n    class.subject.detail\\n\\nHere \'class\' is either 2, 4, or 5 and both \'subject\' and\\n\'detail\'  are integers in the range 0..999. Given a status\\ncode the corresponding index value is defined to be\\n((class * 1000) + subject) * 1000 + detail.  Both SMTP\\nerror response codes and X.400 reason and diagnostic codes\\ncan be mapped into these codes, resulting in a namespace\\n\\ncapable of describing most error conditions a mail system\\nencounters in a generic yet detailed way.\",\"index\":[],\"name\":\"mtaConformance\",\"objectID\":\"1.3.6.1.2.1.28.4\",\"pid\":\"1.3.6.1.2.1.28\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"An index capable of representing an Enhanced Mail System\\nStatus Code.  Enhanced Mail System Status Codes are\\ndefined in RFC 1893.  These codes have the form\\n\\n    class.subject.deta